class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        res = []
        for i, row in enumerate(grid):
            if i % 2 == 0:
                cols = range(len(row))
            else:
                cols = range(len(row)-1, -1, -1)
            for j in cols:
                if (i + j) % 2 == 0:
                    res.append(row[j])
