class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        from functools import lru_cache
        @lru_cache(None)
        def dfs(i, mask):
            # mask indicates which of the first three elements starting at i are present
            # mask bits: 0->i, 1->i+1, 2->i+2
            # count present
            present = [i + j for j in range(3) if mask & (1 << j) and i + j < n]
            if not present:
                return 0
            if len(present) <= 3:
                return max(nums[p] for p in present)
            best = float('inf')
            # pick two to remove among present
            for a in range(len(present)):
                for b in range(a + 1, len(present)):
                    rem = [present[k] for k in range(len(present)) if k not in (a, b)]
                    cost = max(nums[rem[0]], nums[rem[1]]) if len(rem) >= 2 else nums[rem[0]]
                    # shift remaining elements to front
                    new_i = rem[0]
                    new_mask = 0
                    for idx, p in enumerate(rem):
                        if p - new_i < 3:
                            new_mask |= 1 << (p - new_i)
                    best = min(best, cost + dfs(new_i, new_mask))
            return best
        # initial mask: all first three present
        init_mask = 0
        for j in range(3):
            if j < n:
                init_mask |= 1 << j
        return dfs(0, init_mask)
