class Solution:
    def minCost(self, nums: List[int]) -> int:
        from functools import lru_cache
        n = len(nums)
        @lru_cache(None)
        def dfs(i: int) -> int:
            if i >= n:
                return 0
            remaining = n - i
            if remaining < 3:
                return max(nums[i:])
            # choose pairs among first three
            best = float('inf')
            # remove i and i+1
            cost = max(nums[i], nums[i+1]) + dfs(i+2)
            best = min(best, cost)
            # remove i and i+2
            cost = max(nums[i], nums[i+2]) + dfs(i+1)
            best = min(best, cost)
            # remove i+1 and i+2
            cost = max(nums[i+1], nums[i+2]) + dfs(i)
            best = min(best, cost)
            return best
        return dfs(0)
