from typing import List

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        cnt = Counter(digits)
        digits_list = list(cnt.keys())
        result = set()
        for d1 in digits_list:
            if d1 == 0:
                continue
            cnt[d1] -= 1
            if cnt[d1] == 0:
                del cnt[d1]
            for d2 in list(cnt.keys()):
                cnt[d2] -= 1
                if cnt[d2] == 0:
                    del cnt[d2]
                for d3 in list(cnt.keys()):
                    if d3 % 2 == 0:
                        result.add(d1 * 100 + d2 * 10 + d3)
                # restore d2
                cnt[d2] = cnt.get(d2, 0) + 1
            # restore d1
            cnt[d1] = cnt.get(d1, 0) + 1
        return len(result)
