import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        n = int(next(it))
    except StopIteration:
        return
    A = [int(next(it)) for _ in range(n)]
    B = [int(next(it)) for _ in range(n)]

    fixed_sum = None
    for a, b in zip(A, B):
        if a != -1 and b != -1:
            s = a + b
            if fixed_sum is None:
                fixed_sum = s
            elif fixed_sum != s:
                print("No")
                return

    lower_bounds = []
    for a, b in zip(A, B):
        if a == -1 and b == -1:
            continue
        if a == -1:
            # need a = S - b >= 0 -> S >= b
            lower_bounds.append(b)
        elif b == -1:
            # need b = S - a >= 0 -> S >= a
            lower_bounds.append(a)
        else:
            # both known already handled
            pass

    if fixed_sum is not None:
        S = fixed_sum
        if S < 0:
            print("No")
            return
        for lb in lower_bounds:
            if S < lb:
                print("No")
                return
        print("Yes")
    else:
        # choose any S >= max(lower_bounds) and >=0
        S = max(lower_bounds) if lower_bounds else 0
        if S < 0:
            print("No")
        else:
            print("Yes")

if __name__ == "__main__":
    solve()
