        n = len(nums)
        from collections import defaultdict
        cnt = defaultdict(int)
        for i in range(n - k + 1):
            window_set = set(nums[i:i+k])
            for v in window_set:
                cnt[v] += 1
        ans = -1
        for v, c in cnt.items():
            if c == 1:
                ans = max(ans, v)
        return ans
