class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        from collections import defaultdict
        count = defaultdict(int)
        n = len(nums)
        for i in range(n - k + 1):
            sub = nums[i:i+k]
            seen = set()
            for x in sub:
                if x not in seen:
                    count[x] += 1
                    seen.add(x)
        res = -1
        for x, c in count.items():
            if c == 1 and x > res:
                res = x
        return res
