from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # precompute factorials up to n with cap
        cap = 10**18
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            val = fact[i-1] * i
            fact[i] = val if val <= cap else cap

        odds = (n + 1) // 2
        evens = n // 2

        # total number of alternating permutations
        total = fact[odds] * fact[evens]
        if n % 2 == 0:
            total *= 2
        if k > total:
            return []

        # helper to count completions from a state
        def count_completions(rem_odds: int, rem_evens: int, next_parity: int) -> int:
            # next_parity: 0 for odd, 1 for even
            if abs(rem_odds - rem_evens) > 1:
                return 0
            if next_parity == 0 and rem_odds == 0:
                return 0
            if next_parity == 1 and rem_evens == 0:
                return 0
            return fact[rem_odds] * fact[rem_evens]

        # generate permutation
        result = []
        used_odds = 0
        used_evens = 0
        prev_parity = None  # None means first position

        for pos in range(n):
            # collect candidates in sorted order
            candidates = []
            if prev_parity is None:
                # first position: all numbers
                if odds > used_odds:
                    for num in range(1, n+1):
                        if num % 2 == 1:
                            candidates.append(num)
                if evens > used_evens:
                    for num in range(1, n+1):
                        if num % 2 == 0:
                            candidates.append(num)
            else:
                # need opposite parity of prev
                needed_parity = 1 - prev_parity
                if needed_parity == 0 and odds > used_odds:
                    for num in range(1, n+1):
                        if num % 2 == 1:
                            candidates.append(num)
                elif needed_parity == 1 and evens > used_evens:
                    for num in range(1, n+1):
                        if num % 2 == 0:
                            candidates.append(num)

            candidates.sort()
            for cand in candidates:
                parity = cand % 2
                # check availability
                if parity == 0 and used_odds >= odds:
                    continue
                if parity == 1 and used_evens >= evens:
                    continue

                # compute completions after picking cand
                rem_odds = odds - (used_odds + (parity == 0))
                rem_evens = evens - (used_evens + (parity == 1))
                next_parity = 1 - parity
                cnt = count_completions(rem_odds, rem_evens, next_parity)

                if k > cnt:
                    k -= cnt
                else:
                    result.append(cand)
                    if parity == 0:
                        used_odds += 1
                    else:
                        used_evens += 1
                    prev_parity = parity
                    break

        return result
```

