from functools import lru_cache
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = [i for i in range(1, n+1) if i % 2 == 1]
        evens = [i for i in range(1, n+1) if i % 2 == 0]
        total_odds = len(odds)
        total_evens = len(evens)

        @lru_cache(maxsize=None)
        def count(o: int, e: int, prev: int) -> int:
            # prev: 0 for odd, 1 for even, -1 for none
            if o == 0 and e == 0:
                return 1
            res = 0
            if prev == -1 or prev == 1:  # we can pick odd
                if o > 0:
                    res += count(o-1, e, 0)
            if prev == -1 or prev == 0:  # we can pick even
                if e > 0:
                    res += count(o, e-1, 1)
            return min(res, 10**15+1)  # cap to avoid huge numbers

        total_perms = count(total_odds, total_evens, -1)
        if k > total_perms:
            return []

        used = [False] * (n + 1)
        result = []
        prev = -1
        o_left, e_left = total_odds, total_evens

        for _ in range(n):
            for val in range(1, n+1):
                if used[val]:
                    continue
                parity = 0 if val % 2 == 1 else 1
                if prev != -1 and parity == prev:
                    continue
                # compute count if we pick this val
                if parity == 0:
                    cnt = count(o_left-1, e_left, 0)
                else:
                    cnt = count(o_left, e_left-1, 1)
                if k > cnt:
                    k -= cnt
                else:
                    # choose this val
                    result.append(val)
                    used[val] = True
                    if parity == 0:
                        o_left -= 1
                    else:
                        e_left -= 1
                    prev = parity
                    break
        return result
