from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = 10**18
        # dp[prev_left][prev_right] = min cost
        dp = [[INF]*3 for _ in range(3)]
        # first pair
        for cl in range(3):
            for cr in range(3):
                if cl != cr:
                    dp[cl][cr] = cost[0][cl] + cost[n-1][cr]
        # process remaining pairs
        for i in range(1, m):
            ndp = [[INF]*3 for _ in range(3)]
            for pl in range(3):
                for pr in range(3):
                    if dp[pl][pr] == INF:
                        continue
                    for cl in range(3):
                        if cl == pl:
                            continue
                        for cr in range(3):
                            if cr == pr or cr == cl:
                                continue
                            val = dp[pl][pr] + cost[i][cl] + cost[n-1-i][cr]
                            if val < ndp[cl][cr]:
                                ndp[cl][cr] = val
            dp = ndp
        return min(min(row) for row in dp)
