from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**18
        m = n // 2
        # dp[prev_left][prev_right] = min cost up to previous pair
        dp = [[INF]*3 for _ in range(3)]
        # initial state: no previous colors, we can use -1 sentinel
        # Use a separate flag for first pair
        first = True
        for i in range(m):
            j = n - 1 - i
            ndp = [[INF]*3 for _ in range(3)]
            for pl in range(3):
                for pr in range(3):
                    cur = dp[pl][pr] if not first else 0
                    if cur >= INF:
                        continue
                    for a in range(3):  # color for left
                        if not first and a == pl:
                            continue
                        for b in range(3):  # color for right
                            if a == b:
                                continue
                            if not first and b == pr:
                                continue
                            val = cur + cost[i][a] + cost[j][b]
                            if val < ndp[a][b]:
                                ndp[a][b] = val
            dp = ndp
            first = False
        # answer is min over dp states
        return min(min(row) for row in dp)
