class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        half = n // 2
        # all valid (left, right) pairs where colors differ
        states = [(l, r) for l in range(3) for r in range(3) if l != r]
        m = len(states)  # 6
        INF = 10**15
        dp_prev = [INF] * m
        # initialize first pair
        i = 0
        j = n - 1
        for idx, (l, r) in enumerate(states):
            dp_prev[idx] = cost[i][l] + cost[j][r]
        # process remaining pairs
        for i in range(1, half):
            j = n - 1 - i
            dp_cur = [INF] * m
            for cur_idx, (l_cur, r_cur) in enumerate(states):
                add = cost[i][l_cur] + cost[j][r_cur]
                best = INF
                for prev_idx, (l_prev, r_prev) in enumerate(states):
                    if l_prev != l_cur and r_prev != r_cur:
                        val = dp_prev[prev_idx] + add
                        if val < best:
                            best = val
                dp_cur[cur_idx] = best
            dp_prev = dp_cur
        return min(dp_prev)
