from typing import List
import heapq

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        # Sliding window median with sums
        left = []  # max heap
        right = []  # min heap
        lsum = 0
        rsum = 0
        lazy = {}
        def add(num):
            nonlocal lsum, rsum
            if not left or num <= -left[0]:
                heapq.heappush(left, -num)
                lsum += num
            else:
                heapq.heappush(right, num)
                rsum += num
            balance()
        def remove(num):
            nonlocal lsum, rsum
            lazy[num] = lazy.get(num, 0) + 1
            if num <= -left[0]:
                lsum -= num
            else:
                rsum -= num
            prune()
            balance()
        def prune():
            while left and lazy.get(-left[0], 0):
                val = -heapq.heappop(left)
                lazy[val] -= 1
            while right and lazy.get(right[0], 0):
                val = heapq.heappop(right)
                lazy[val] -= 1
        def balance():
            nonlocal lsum, rsum
            # left should have size >= right and at most one more
            while len(left) > len(right) + 1:
                val = -heapq.heappop(left)
                lsum -= val
                heapq.heappush(right, val)
                rsum += val
            while len(left) < len(right):
                val = heapq.heappop(right)
                rsum -= val
                heapq.heappush(left, -val)
                lsum += val
        def current_cost():
            med = -left[0]
            return med * len(left) - lsum + rsum - med * len(right)
        # Build cost array
        cost = [0] * (n - x + 1)
        for i in range(x):
            add(nums[i])
        cost[0] = current_cost()
        for i in range(1, n - x + 1):
            remove(nums[i - 1])
            add(nums[i + x - 1])
            cost[i] = current_cost()
        # DP
        INF = 10**18
        dp = [INF] * (k + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            newdp = dp[:]
            if i >= x:
                idx = i - x
                addcost = cost[idx]
                for t in range(1, k + 1):
                    if dp[t - 1] + addcost < newdp[t]:
                        newdp[t] = dp[t - 1] + addcost
            for t in range(k + 1):
                if dp[t] < newdp[t]:
                    newdp[t] = dp[t]
            dp = newdp
        return dp[k]
