from typing import List
import heapq

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        INF = 10**18

        # sliding window median with two heaps
        maxh, minh = [], []          # maxh as negatives
        summax, summin = 0, 0
        lazy = {}
        def add(val):
            nonlocal summax, summin
            heapq.heappush(maxh, -val)
            summax += val
            balance()
        def remove(val):
            nonlocal summax, summin
            lazy[val] = lazy.get(val, 0) + 1
            if val <= -maxh[0]:
                summax -= val
            else:
                summin -= val
            prune(maxh)
            prune(minh)
            balance()
        def prune(h):
            while h and lazy.get((-h[0] if h==maxh else h[0]), 0):
                val = -heapq.heappop(h) if h==maxh else heapq.heappop(h)
                lazy[val] -= 1
                if lazy[val]==0:
                    del lazy[val]
        def balance():
            nonlocal summax, summin
            if len(maxh) > len(minh)+1:
                val = -heapq.heappop(maxh)
                summax -= val
                heapq.heappush(minh, val)
                summin += val
            elif len(minh) > len(maxh):
                val = heapq.heappop(minh)
                summin -= val
                heapq.heappush(maxh, -val)
                summax += val
        def median():
            return -maxh[0]
        def cost():
            med = median()
            left = -len(maxh)
            right = len(minh)
            return med*left - summax + summin - med*right

        cost_arr = [0]*(n - x + 1)
        for i in range(n):
            add(nums[i])
            if i >= x:
                remove(nums[i - x])
            if i >= x - 1:
                cost_arr[i - x + 1] = cost()

        # DP
        dp = [ [INF]*(k+1) for _ in range(n+1) ]
        dp[0][0] = 0
        ans = INF
        for i in range(n):
            for cnt in range(k+1):
                cur = dp[i][cnt]
                if cur==INF: continue
                # skip
                if dp[i+1][cnt] > cur:
                    dp[i+1][cnt] = cur
                # take window
                if i + x <= n and cnt < k:
                    new = cur + cost_arr[i]
                    if dp[i+x][cnt+1] > new:
                        dp[i+x][cnt+1] = new
                    if cnt+1==k:
                        if ans > new:
                            ans = new
        return ans
