class Solution:
    def minimumCost(self, nums, cost, k):
        n = len(nums)
        pref_nums = [0]*(n+1)
        pref_cost = [0]*(n+1)
        for i in range(1,n+1):
            pref_nums[i] = pref_nums[i-1] + nums[i-1]
            pref_cost[i] = pref_cost[i-1] + cost[i-1]
        INF = 10**18
        # dp[t][i]: minimal cost to cover first i elements with t subarrays
        dp = [[INF]*(n+1) for _ in range(n+1)]
        dp[0][0] = 0
        for t in range(1, n+1):
            for i in range(1, n+1):
                # try all possible start positions for the t-th subarray
                best = INF
                for l in range(1, i+1):
                    prev = dp[t-1][l-1]
                    if prev == INF: 
                        continue
                    sum_nums = pref_nums[i] - pref_nums[l-1]
                    sum_cost = pref_cost[i] - pref_cost[l-1]
                    cur = prev + (sum_nums + k*t) * sum_cost
                    if cur < best:
                        best = cur
                dp[t][i] = best
        # answer is min over all t
        return min(dp[t][n] for t in range(1, n+1))
