class Solution:
    def maxSum(self, nums: list[int], k: int, m: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, v in enumerate(nums):
            pref[i + 1] = pref[i] + v
        # best_end[i] = max sum of subarray ending at i with length >= m
        best_end = [0] * n
        for i in range(n):
            best = float("-inf")
            for l in range(m, i + 2):
                s = pref[i + 1] - pref[i + 1 - l]
                if s > best:
                    best = s
            best_end[i] = best
        NEG = float("-inf")
        dp = [[NEG] * (k + 1) for _ in range(n)]
        for i in range(n):
            dp[i][0] = 0
        for i in range(n):
            for t in range(1, k + 1):
                # skip current index
                if i > 0:
                    dp[i][t] = dp[i - 1][t]
                # take subarray ending at i
                for l in range(m, i + 2):
                    prev = i - l
                    val = best_end[i]
                    if prev >= 0:
                        cand = dp[prev][t - 1] + val
                    else:
                        cand = val if t == 1 else NEG
                    if cand > dp[i][t]:
                        dp[i][t] = cand
        return dp[n - 1][k]
