        n = len(nums)
        pref = [0]*(n+1)
        for i in range(n):
            pref[i+1] = pref[i] + nums[i]
        INF = 10**18
        dp = [[-INF]*(k+1) for _ in range(n+1)]
        best_end = [[-INF]*(k+1) for _ in range(n+1)]
        dp[0][0] = 0
        for i in range(1, n+1):
            dp[i][0] = 0
            for j in range(1, k+1):
                # propagate previous best_end
                if best_end[i-1][j] > -INF:
                    best_end[i][j] = max(best_end[i][j], best_end[i-1][j] + nums[i-1])
                # start new subarray of length m ending at i
                if i >= m:
                    val = dp[i-m][j-1] + (pref[i]-pref[i-m])
                    if val > best_end[i][j]:
                        best_end[i][j] = val
                # dp transition
                if dp[i-1][j] > dp[i][j]:
                    dp[i][j] = dp[i-1][j]
                if best_end[i][j] > dp[i][j]:
                    dp[i][j] = best_end[i][j]
        return dp[n][k]
