        n = len(nums)
        total = 0
        for l in range(n):
            last = nums[l]
            cost = 0
            for r in range(l, n):
                if r > l:
                    inc = max(0, last - nums[r])
                    cost += inc
                    last = max(last, nums[r])
                if cost <= k:
                    total += 1
