    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(limit: int) -> int:
            s = str(limit)
            n = len(s)
            from functools import lru_cache
            @lru_cache(None)
            def dfs(pos, tight, sum_so_far, prod_mod, prod_val, started):
                if pos == n:
                    if not started:
                        return 0
                    if sum_so_far == 0:
                        return 0
                    return 1 if prod_val % sum_so_far == 0 else 0
                res = 0
                up = int(s[pos]) if tight else 9
                for d in range(0, up + 1):
                    ntight = tight and d == up
                    nstarted = started or d != 0
                    nsum = sum_so_far
                    nprod = prod_val
                    if nstarted:
                        nsum += d
                        nprod *= d
                    res += dfs(pos + 1, ntight, nsum, prod_mod, nprod, nstarted)
                return res
            return dfs(0, True, 0, 0, 1, False)
        return count(r) - count(l - 1)
