import sys

def count_snake(n: int) -> int:
    if n < 10:
        return 0
    s = str(n)
    length = len(s)
    total = 0

    # lengths shorter than n
    for d in range(1, length):
        for t in range(1, 10):
            total += t ** (d - 1)

    first_digit = int(s[0])
    suffix = s[1:]

    # same length
    for t in range(1, 10):
        if t > first_digit:
            total += t ** (length - 1)
        elif t == first_digit:
            # count numbers with top digit t and rest <= suffix, digits < t
            k = length - 1
            ways = 0
            for i in range(k):
                cur = int(suffix[i])
                # digits less than cur but < t
                limit = min(cur - 1, t - 1)
                if limit >= 0:
                    ways += (limit + 1) * (t ** (k - i - 1))
                if cur >= t:
                    # cannot use cur, stop
                    break
            else:
                # all digits were < t
                ways += 1
            total += ways
    return total

