from collections import deque, defaultdict
from typing import List

class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
    def add_edge(self, u, v, c):
        self.adj[u].append([v, c, len(self.adj[v])])
        self.adj[v].append([u, 0, len(self.adj[u])-1])
    def bfs(self, s, t, level):
        q = deque([s])
        level[s] = 0
        while q:
            u = q.popleft()
            for v, cap, rev in self.adj[u]:
                if cap and level[v] < 0:
                    level[v] = level[u] + 1
                    q.append(v)
        return level[t] >= 0
    def dfs(self, u, t, f, level, it):
        if u == t:
            return f
        for i in range(it[u], len(self.adj[u])):
            it[u] = i
            v, cap, rev = self.adj[u][i]
            if cap and level[u] + 1 == level[v]:
                ret = self.dfs(v, t, min(f, cap), level, it)
                if ret:
                    self.adj[u][i][1] -= ret
                    self.adj[v][rev][1] += ret
                    return ret
        return 0
    def max_flow(self, s, t):
        flow = 0
        level = [-1]*self.n
        while self.bfs(s, t, level):
            it = [0]*self.n
            while True:
                f = self.dfs(s, t, 10**18, level, it)
                if not f:
                    break
                flow += f
            level = [-1]*self.n
        return flow

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        if n == 1:
            return 0
        weights = sorted(set(w for _,_,w in edges))
        if not weights:
            return -1
        def feasible(limit):
            # build adjacency for bipartite graph
            children = list(range(n))
            parent_nodes = list(range(n))
            idx_child = [i for i in range(n)]
            idx_parent = [n + i for i in range(n)]
            source = 2*n
            sink = source + 1
            din = Dinic(2*n + 2)
            # source to child
            for u in range(1, n):
                din.add_edge(source, idx_child[u], 1)
            # parent to sink
            for v in range(n):
                din.add_edge(idx_parent[v], sink, threshold)
            # edges
            for a,b,w in edges:
                if w <= limit:
                    if a==0:  # child cannot be root
                        continue
                    din.add_edge(idx_child[a], idx_parent[b], 1)
            flow = din.max_flow(source, sink)
            return flow == n-1
        lo, hi = 0, len(weights)-1
        ans = -1
        while lo <= hi:
