from typing import List
from collections import defaultdict, deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # threshold is irrelevant for feasibility as explained
        weights = sorted({w for _,_,w in edges})
        if not weights:
            return -1
        # Build adjacency by weight threshold
        def can(wmax: int) -> bool:
            rev = defaultdict(list)
            for a,b,w in edges:
                if w <= wmax:
                    rev[b].append(a)
            vis = [False]*n
            q = deque([0])
            vis[0] = True
            while q:
                u = q.popleft()
                for v in rev[u]:
                    if not vis[v]:
                        vis[v] = True
                        q.append(v)
            return all(vis)
        lo, hi = 0, len(weights)-1
        ans = -1
        while lo <= hi:
            mid = (lo+hi)//2
            if can(weights[mid]):
                ans = weights[mid]
                hi = mid-1
            else:
                lo = mid+1
        return ans
