class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        # Segment tree storing maximum capacity in each segment
        size = 1
        while size < n:
            size <<= 1
        seg = [0] * (2 * size)
        for i, val in enumerate(baskets):
            seg[size + i] = val
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(pos: int, val: int):
            idx = size + pos
            seg[idx] = val
            idx >>= 1
            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx >>= 1

        def query_first_ge(node: int, node_l: int, node_r: int, l: int, r: int, target: int) -> int:
            if node_r < l or node_l > r or seg[node] < target:
                return -1
            if node_l == node_r:
                return node_l
            mid = (node_l + node_r) >> 1
            left = query_first_ge(2 * node, node_l, mid, l, r, target)
            if left != -1:
                return left
            return query_first_ge(2 * node + 1, mid + 1, node_r, l, r, target)

        unplaced = 0
        for f in fruits:
            idx = query_first_ge(1, 0, size - 1, 0, n - 1, f)
            if idx == -1 or idx >= n:
                unplaced += 1
            else:
                update(idx, 0)
        return unplaced
