            seg[size + i] = v
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(pos: int):
            idx = size + pos
            seg[idx] = 0  # mark used
            idx >>= 1
            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx >>= 1

        def query(val: int, node: int, l: int, r: int) -> int:
            if seg[node] < val:
                return -1
            if l == r:
                return l
            mid = (l + r) // 2
            left = node * 2
            res = query(val, left, l, mid)
            if res != -1:
                return res
            return query(val, left + 1, mid + 1, r)

        unplaced = 0
        for f in fruits:
            idx = query(f, 1, 0, size - 1)
            if idx == -1 or idx >= n:
                unplaced += 1
            else:
                update(idx)
        return unplaced
