        n = len(fruits)
        size = 1
        while size < n:
            size <<= 1
        seg = [0] * (2 * size)
        # build leaf nodes
        for i in range(n):
            seg[size + i] = baskets[i]
        # build internal nodes
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(idx: int):
            pos = size + idx
            seg[pos] = 0  # mark used
            pos //= 2
            while pos:
                seg[pos] = max(seg[2 * pos], seg[2 * pos + 1])
                pos //= 2

        def query(val: int) -> int:
            if seg[1] < val:
                return -1
            pos = 1
            while pos < size:
                if seg[2 * pos] >= val:
                    pos = 2 * pos
                else:
                    pos = 2 * pos + 1
            return pos - size

        unplaced = 0
        for fruit in fruits:
            idx = query(fruit)
            if idx == -1:
                unplaced += 1
            else:
                update(idx)
        return unplaced
