class Solution:
    def numberOfComponents(self, properties: list[list[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[ry] < rank[rx]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # Precompute sets for each property list
        sets = [set(row) for row in properties]

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        roots = {find(i) for i in range(n)}
        return len(roots)
