import sys

def fwht(a, inverse=False):
    n = len(a)
    h = 1
    while h < n:
        for i in range(0, n, h * 2):
            for j in range(i, i + h):
                x = a[j]
                y = a[j + h]
                a[j] = x + y
                a[j + h] = x - y
        h <<= 1
    if inverse:
        inv_n = 1 / n
        for i in range(n):
            a[i] *= inv_n

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    H = int(data[0]); W = int(data[1])
    rows = data[2:]
    n = 1 << W
    freq = [0] * n
    for s in rows:
        mask = int(s, 2)
        freq[mask] += 1
    f = [0] * n
    for x in range(n):
        pc = x.bit_count()
        f[x] = min(pc, W - pc)
    fwht(freq)
    fwht(f)
    for i in range(n):
        freq[i] *= f[i]
    fwht(freq, inverse=True)
    print(int(min(freq)))

if __name__ == "__main__":
    main()
