def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    S = next(it).strip()
    T = next(it).strip()

    mapping = {}
    for a, b in zip(S, T):
        if a == b:
            continue
        if a in mapping:
            if mapping[a] != b:
                print(-1)
                return
        else:
            mapping[a] = b

    # Build graph of 26 letters
    g = {chr(ord('a') + i): [] for i in range(26)}
    for u, v in mapping.items():
        g[u].append(v)

    # Tarjan SCC
    index = 0
    indices = {}
    lowlink = {}
    stack = []
    onstack = set()
    scc_sizes = []

    def strongconnect(v):
        nonlocal index
        indices[v] = lowlink[v] = index
        index += 1
        stack.append(v)
        onstack.add(v)
        for w in g[v]:
            if w not in indices:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif w in onstack:
                lowlink[v] = min(lowlink[v], indices[w])
        if lowlink[v] == indices[v]:
            size = 0
            while True:
                w = stack.pop()
                onstack.remove(w)
                size += 1
                if w == v:
                    break
            scc_sizes.append(size)

    for v in g:
        if v not in indices:
            strongconnect(v)

    ops = len(mapping)
    for sz in scc_sizes:
        if sz > 1:
            ops += sz  # extra 1 per cycle
    print(ops)

if __name__ == "__main__":
    solve()
