        visited[u] = 1
        for v in graph[u]:
            if v not in visited:
                dfs(v)
                if cycle:
                    return
            elif visited[v] == 1:
                cycle = True
                return
        visited[u] = 2

    for u in graph:
        if u not in visited:
            dfs(u)
            if cycle:
                break

    ops = len(edges) + (1 if cycle else 0)
