def solve() -> None:
    it = iter(sys.stdin.read().split())
    N = int(next(it)); M = int(next(it)); X = int(next(it))
    out_adj = [[] for _ in range(N+1)]
    rev_adj = [[] for _ in range(N+1)]
    for _ in range(M):
        u = int(next(it)); v = int(next(it))
        out_adj[u].append(v)
        rev_adj[v].append(u)

    INF = 10**30
    dist0 = [INF]*(N+1)
    dist1 = [INF]*(N+1)
    dist0[1] = 0
    hq = [(0, 1, 0)]  # (cost, node, orientation)
    while hq:
        d, u, o = heapq.heappop(hq)
        if o == 0:
            if d != dist0[u]: continue
        else:
            if d != dist1[u]: continue
        # move along edges
        if o == 0:
            for v in out_adj[u]:
                nd = d + 1
                if nd < dist0[v]:
                    dist0[v] = nd
                    heapq.heappush(hq, (nd, v, 0))
        else:
            for v in rev_adj[u]:
                nd = d + 1
                if nd < dist1[v]:
                    dist1[v] = nd
                    heapq.heappush(hq, (nd, v, 1))
        # reverse orientation
        nd = d + X
        if o == 0:
            if nd < dist1[u]:
                dist1[u] = nd
                heapq.heappush(hq, (nd, u, 1))
        else:
            if nd < dist0[u]:
                dist0[u] = nd
                heapq.heappush(hq, (nd, u, 0))

    ans = min(dist0[N], dist1[N])
    print(ans)

if __name__ == "__main__":
