class Solution:
    def longestCommonPrefix(self, words, k):
        class Node:
            __slots__ = ("cnt","children")
            def __init__(self):
                self.cnt = 0
                self.children = {}
        root = Node()
        for w in words:
            node = root
            node.cnt += 1
            for ch in w:
                node = node.children.setdefault(ch, Node())
                node.cnt += 1
        # DFS to collect depths where cnt>=k
        best1 = 0
        best2 = 0
        def dfs(node, depth):
            nonlocal best1, best2
            if node.cnt >= k:
                if depth > best1:
                    best2 = best1
                    best1 = depth
                elif depth > best2:
                    best2 = depth
            for child in node.children.values():
                dfs(child, depth+1)
        dfs(root, 0)
        res = []
        for w in words:
            node = root
            best = best1
            if node.cnt - 1 >= k:  # root depth 0 always valid
                pass
            else:
                best = best2
            for ch in w:
                node = node.children[ch]
                if node.cnt - 1 >= k:
                    best = max(best, len(w[:w.index(ch)+1]))
                else:
                    if best == len(w[:w.index(ch)+1]):
                        best = best2
            res.append(best)
        return res
