class Solution:
    def longestCommonPrefix(self, words: list[str], k: int) -> list[int]:
        # build trie
        trie = [{'next': {}, 'cnt': 0, 'depth': 0}]
        for w in words:
            node = 0
            trie[node]['cnt'] += 1
            for ch in w:
                if ch not in trie[node]['next']:
                    trie.append({'next': {}, 'cnt': 0, 'depth': trie[node]['depth'] + 1})
                    trie[node]['next'][ch] = len(trie) - 1
                node = trie[node]['next'][ch]
                trie[node]['cnt'] += 1

        ans = []
        for w in words:
            node = 0
            best = 0
            for ch in w:
                node = trie[node]['next'][ch]
                if trie[node]['cnt'] >= k + 1:
                    best = trie[node]['depth']
            ans.append(best)
        return ans
