class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w))
            g[v].append((u, w))

        self.max_len = 0
        self.min_nodes = n + 1

        def dfs(u, p):
            # dict: value -> (dist, nodes)
            d = {nums[u]: (0, 1)}
            for v, w in g[u]:
                if v == p: continue
                child = dfs(v, u)
                for val, (dist, nodes) in child.items():
                    if val == nums[u]:
                        continue
                    nd = dist + w
                    if val not in d or nd > d[val][0]:
                        d[val] = (nd, nodes)
            # update global
            for dist, nodes in d.values():
                if dist > self.max_len:
                    self.max_len = dist
                    self.min_nodes = nodes
                elif dist == self.max_len and nodes < self.min_nodes:
                    self.min_nodes = nodes
            return d

        dfs(0, -1)
        return [self.max_len, self.min_nodes]
