from typing import List

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        g = [[] for _ in range(n)]
        for u, v, l in edges:
            g[u].append((v, l))
            g[v].append((u, l))
        best_len = 0
        best_cnt = 1

        def dfs(u: int, parent: int, seen: set, cur_len: int, cur_cnt: int):
            nonlocal best_len, best_cnt
            val = nums[u]
            if val in seen:
                # start new path at u
                seen = {val}
                cur_len = 0
                cur_cnt = 1
            else:
                seen.add(val)
            # update best
            if cur_len > best_len:
                best_len = cur_len
                best_cnt = cur_cnt
            elif cur_len == best_len:
                if cur_cnt < best_cnt:
                    best_cnt = cur_cnt
            for v, w in g[u]:
                if v == parent:
                    continue
                dfs(v, u, seen.copy(), cur_len + w, cur_cnt + 1)

        dfs(0, -1, set(), 0, 1)
        return [best_len, best_cnt]
