import heapq

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # parse events to (timestamp, priority, type, data)
        # priority: OFFLINE -> 0, MESSAGE -> 1
        parsed = []
        for ev in events:
            typ, ts, data = ev[0], int(ev[1]), ev[2]
            pr = 0 if typ == "OFFLINE" else 1
            parsed.append((ts, pr, typ, data))
        parsed.sort()  # sort by timestamp, then priority

        mentions = [0] * numberOfUsers
        online = set(range(numberOfUsers))
        # min-heap of (end_time, user) for offline periods
        heap = []

        for ts, _, typ, data in parsed:
            # expire offline users up to current timestamp
            while heap and heap[0][0] <= ts:
                _, uid = heapq.heappop(heap)
                online.add(uid)

            if typ == "OFFLINE":
                uid = int(data)
                if uid in online:
                    online.remove(uid)
                    heapq.heappush(heap, (ts + 60, uid))
            else:  # MESSAGE
                if data == "ALL":
                    for uid in range(numberOfUsers):
                        mentions[uid] += 1
                elif data == "HERE":
                    for uid in online:
                        mentions[uid] += 1
                else:
                    tokens = data.split()
                    for token in tokens:
                        if token.startswith("id"):
                            uid = int(token[2:])
                            mentions[uid] += 1
        return mentions
