class Solution:
    def countMentions(self, numberOfUsers: int, events: list[list[str]]) -> list[int]:
        # Prepare events with timestamp as int and type priority
        processed = []
        for e in events:
            typ, ts_str, data = e
            ts = int(ts_str)
            priority = 0 if typ == "OFFLINE" else 1  # OFFLINE before MESSAGE on same ts
            processed.append((ts, priority, typ, data))
        processed.sort()  # sort by timestamp, then priority

        # All users initially online
        offline_until = [0] * numberOfUsers  # timestamp until which user is offline (exclusive)
        mentions = [0] * numberOfUsers

        for ts, _, typ, data in processed:
            # Update status for each user if they become online at this timestamp
            # (handled implicitly by checking offline_until)

            if typ == "OFFLINE":
                uid = int(data)
                offline_until[uid] = ts + 60  # offline until ts+60 (exclusive)
            else:  # MESSAGE
                # Determine current online users
                online_mask = [ts < offline_until[i] for i in range(numberOfUsers)]
                if data == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif data == "HERE":
                    for i in range(numberOfUsers):
                        if not online_mask[i]:
                            continue
                        mentions[i] += 1
                else:
                    tokens = data.split()
                    for tok in tokens:
                        if tok.startswith("id"):
                            uid = int(tok[2:])
                            mentions[uid] += 1
        return mentions
