def int_cuberoot(n):
    lo, hi = 0, int(round(n ** (1/3))) + 2
    while lo <= hi:
        mid = (lo + hi) // 2
        cube = mid * mid * mid
        if cube == n:
            return mid
        if cube < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

