class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k > n:
            return False
        i = 0
        while i <= n - k:
            # check if s[i:i+k] all same
            if s[i] * k == s[i:i+k]:
                # check left boundary
                if i > 0 and s[i-1] == s[i]:
                    i += 1
                    continue
                # check right boundary
                if i + k < n and s[i + k] == s[i]:
                    i += 1
                    continue
                return True
            # move to next position
            i += 1
        return False
