import sys
sys.setrecursionlimit(1 << 25)
MOD = 998244353

def solve() -> None:
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    M = int(next(it))
    A = [int(next(it)) - 1 for _ in range(N)]

    # Build graph
    g = [[] for _ in range(N)]
    for i, a in enumerate(A):
        g[i].append(a)

    # Kosaraju SCC
    visited = [False] * N
    order = []

    def dfs1(v):
        visited[v] = True
        for to in g[v]:
            if not visited[to]:
                dfs1(to)
        order.append(v)

    for v in range(N):
        if not visited[v]:
            dfs1(v)

    rev_g = [[] for _ in range(N)]
    for v in range(N):
        for to in g[v]:
            rev_g[to].append(v)

    comp_id = [-1] * N
    cid = 0

    def dfs2(v, cl):
        comp_id[v] = cl
        for to in rev_g[v]:
            if comp_id[to] == -1:
                dfs2(to, cl)

    for v in reversed(order):
        if comp_id[v] == -1:
            dfs2(v, cid)
            cid += 1

    K = cid
    comp_par = [-1] * K
    comp_children = [[] for _ in range(K)]
    for v in range(N):
        cv = comp_id[v]
        av = comp_id[A[v]]
        if cv != av:
            comp_par[cv] = av

    # Build children list
    for v in range(K):
        p = comp_par[v]
        if p != -1:
            comp_children[p].append(v)

    # Find roots
    roots = [i for i in range(K) if comp_par[i] == -1]

    # DP
    f = [[0] * (M + 1) for _ in range(K)]
    # Post-order traversal
    sys.setrecursionlimit(1 << 25)
    visited2 = [False] * K
    order2 = []

    def dfs3(v):
        visited2[v] = True
        for to in comp_children[v]:
            if not visited2[to]:
                dfs3(to)
        order2.append(v)

    for r in roots:
        if not visited2[r]:
            dfs3(r)

    for v in order2:
        if not comp_children[v]:
            # leaf
            for val in range(1, M + 1):
                f[v][val] = 1
        else:
            # compute prefix sums for children
            child_prefix = []
            for c in comp_children[v]:
                pref = [0] * (M + 1)
                s = 0
                for val in range(1, M + 1):
                    s = (s + f[c][val]) % MOD
                    pref[val] = s
                child_prefix.append(pref)
            for val in range(1, M + 1):
                prod = 1
                for pref in child_prefix:
                    prod = (prod * pref[val]) % MOD
                f[v][val] = prod

    # Sum over roots
    ans = 0
    for r in roots:
        ans = (ans + sum(f[r][1:])) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
```

