class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        n = len(grid)
        dp = [-10**18] * (k + 1)
        dp[0] = 0
        for i in range(n):
            row = sorted(grid[i], reverse=True)
            pref = [0]
            for v in row:
                pref.append(pref[-1] + v)
            max_take = min(limits[i], len(row), k)
            newdp = dp[:]
            for take in range(1, max_take + 1):
                val = pref[take]
                for cnt in range(k, take - 1, -1):
                    if dp[cnt - take] + val > newdp[cnt]:
                        newdp[cnt] = dp[cnt - take] + val
            dp = newdp
        return max(dp[:k + 1])
