        n = len(grid)
        dp = [0] * (k + 1)
        for i in range(n):
            row = sorted(grid[i], reverse=True)
            pref = [0]
            for val in row:
                pref.append(pref[-1] + val)
            max_take = min(limits[i], len(row), k)
            old_dp = dp[:]
            for j in range(k + 1):
                if old_dp[j] == 0 and j != 0:
                    continue
                for t in range(1, max_take + 1):
                    if j + t > k:
                        break
                    dp[j + t] = max(dp[j + t], old_dp[j] + pref[t])
        return max(dp)
