import sys
def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it)); M = int(next(it)); Q = int(next(it))
    S = [0]*M; T = [0]*M
    for i in range(M):
        S[i] = int(next(it)); T[i] = int(next(it))
    Lq = [0]*Q; Rq = [0]*Q
    for i in range(Q):
        Lq[i] = int(next(it)); Rq[i] = int(next(it))
    # For each edge, store lists of interior and last indices
    interior = [[] for _ in range(N)]  # edges 1..N-1, use 1-indexed
    last = [[] for _ in range(N)]
    for idx in range(1, M+1):
        s = S[idx-1]; t = T[idx-1]
        l = min(s,t); r = max(s,t)
        if r - l >= 2:
            for e in range(l, r-1):
                if e == r-1:
                    last[e].append(idx)
                else:
                    interior[e].append(idx)
    # Build list of conflict points (i,j) where i < j and i is interior, j is last
    pairs = []
    for e in range(1, N):
        ints = interior[e]
        lasts = last[e]
        if ints and lasts:
            for i in ints:
                for j in lasts:
                    if i < j:
                        pairs.append((i,j))
                    elif j < i:
                        pairs.append((j,i))
    # Sort pairs by first
    pairs.sort()
    # Build for each start index the minimal end index among pairs
    min_end = [M+1]*(M+2)
    ptr = 0
    for i in range(1, M+1):
        while ptr < len(pairs) and pairs[ptr][0] == i:
            if pairs[ptr][1] < min_end[i]:
                min_end[i] = pairs[ptr][1]
            ptr += 1
    # Build suffix minimum of min_end
    suff_min = [M+1]*(M+3)
    for i in range(M, 0, -1):
        suff_min[i] = min(min_end[i], suff_min[i+1])
    out = []
    for l,r in zip(Lq,Rq):
        if suff_min[l] <= r:
            out.append("No")
        else:
            out.append("Yes")
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
