class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        pizzas.sort(reverse=True)
        groups = []
        for i in range(0, len(pizzas), 4):
            g = pizzas[i:i+4]
            g.sort()  # ascending
            groups.append((g[3], g[2]))  # largest, second largest
        groups.sort(key=lambda x: x[0], reverse=True)
        half = len(groups) // 2
        total = 0
        for i, (max_val, second) in enumerate(groups):
            if i < half:
                total += max_val  # odd day
            else:
                total += second   # even day
        return total
