class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[parity][sum] = max product <= limit
        dp = [{}, {}]  # parity 0 and 1
        for num in nums:
            ndp = [{}, {}]
            # start new subsequence
            if num <= limit:
                ndp[1][num] = max(ndp[1].get(num, -1), num)
            # extend existing subsequences
            for parity in (0, 1):
                for s, prod in dp[parity].items():
                    newparity = 1 - parity
                    newsum = s + num if parity == 0 else s - num
                    newprod = prod * num
                    if newprod <= limit:
                        cur = ndp[newparity].get(newsum, -1)
                        if newprod > cur:
                            ndp[newparity][newsum] = newprod
            # merge ndp into dp keeping maximums
            for parity in (0, 1):
                for s, prod in ndp[parity].items():
                    cur = dp[parity].get(s, -1)
                    if prod > cur:
                        dp[parity][s] = prod
        ans = -1
        for parity in (0, 1):
            ans = max(ans, dp[parity].get(k, -1))
        return ans
