        # dp[parity][sum] = max product
        dp = [dict(), dict()]  # parity 0: even length, 1: odd length
        for num in nums:
            new_dp0, new_dp1 = dp[0].copy(), dp[1].copy()
            # start new subsequence
            if num <= limit:
                new_dp1[num] = max(new_dp1.get(num, 0), num)
            # extend existing
            for parity in (0, 1):
                ndp = new_dp1 if parity == 0 else new_dp0
                for s, prod in dp[parity].items():
                    new_sum = s + (num if parity == 0 else -num)
                    new_prod = prod * num
                    if new_prod <= limit:
                        if new_prod > ndp.get(new_sum, 0):
                            ndp[new_sum] = new_prod
            dp[0], dp[1] = new_dp0, new_dp1
        ans = max(dp[0].get(k, 0), dp[1].get(k, 0))
        return ans if ans > 0 else -1
