        # dp[parity][sum] = (max_product, min_len)
        dp = [{0: (1, 0)}, {}]   # parity 0 and 1
        for num in nums:
            ndp0, ndp1 = dp[0].copy(), dp[1].copy()
            for parity in (0, 1):
                for s, (prod, ln) in dp[parity].items():
                    # skip: already in ndp
                    # include
                    new_parity = 1 - parity
                    new_sum = s + (num if parity == 0 else -num)
                    new_prod = prod * num
                    if new_prod <= limit:
                        cur = ndp1 if new_parity == 1 else ndp0
                        if new_sum not in cur or new_prod > cur[new_sum][0] or (new_prod == cur[new_sum][0] and ln+1 < cur[new_sum][1]):
                            cur[new_sum] = (new_prod, ln + 1)
            dp[0], dp[1] = ndp0, ndp1

        best = -1
        for parity in (0, 1):
            if k in dp[parity]:
                prod, ln = dp[parity][k]
                if ln > 0 and prod <= limit:
                    best = max(best, prod)
        return best if best != -1 else -1
