from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        max_abs_sum = 12 * len(nums)
        offset = max_abs_sum
        size = 2 * max_abs_sum + 1
        # dp[sum_offset][parity] -> (product, length)
        dp = [[(-1, 0) for _ in range(2)] for _ in range(size)]
        dp[offset][0] = (1, 0)  # empty subsequence

        for x in nums:
            new_dp = [row[:] for row in dp]
            for s in range(size):
                for parity in (0, 1):
                    prod, length = dp[s][parity]
                    if prod == -1:
                        continue
                    # include x
                    new_sum = s + (x if parity == 0 else -x)
                    if 0 <= new_sum < size:
                        new_prod = prod * x
                        if new_prod <= limit:
                            new_len = length + 1
                            cur_prod, cur_len = new_dp[new_sum][1 - parity]
                            if new_prod > cur_prod or (new_prod == cur_prod and new_len > cur_len):
                                new_dp[new_sum][1 - parity] = (new_prod, new_len)
            dp = new_dp

        target = k + offset
        best = -1
        if 0 <= target < size:
            for parity in (0, 1):
                prod, length = dp[target][parity]
                if prod != -1 and length > 0:
                    best = max(best, prod)
        return best
