class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        # dp_start[dir][parity][r][c]
        dp_start = [[[[0]*m for _ in range(n)] for _ in range(2)] for _ in range(4)]
        # compute in reverse order for each dir
        for d, (dr, dc) in enumerate(dirs):
            # order depends on direction: we need to traverse from farthest to nearest
            r_range = range(n-1, -1, -1) if dr>0 else range(n)
            c_range = range(m-1, -1, -1) if dc>0 else range(m)
            for r in r_range:
                for c in c_range:
                    if grid[r][c] != 1:
                        continue
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                        # parity 0 expects 2 next
                        next_len = dp_start[d][1][nr][nc]
                        dp_start[d][0][r][c] = 1 + next_len
                    else:
                        dp_start[d][0][r][c] = 1
                    # parity 1 expects 0 next
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 0:
                        next_len = dp_start[d][0][nr][nc]
                        dp_start[d][1][r][c] = 1 + next_len
                    else:
                        dp_start[d][1][r][c] = 1
        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                for d, (dr, dc) in enumerate(dirs):
                    # no turn
                    ans = max(ans, dp_start[d][0][r][c])
                    # try turning at each step
                    # traverse along dir
                    steps = 0
                    parity = 0
                    cr, cc = r, c
                    while 0 <= cr < n and 0 <= cc < m:
                        if grid[cr][cc] != 1:
                            break
                        # try turn here if not first cell
                        if steps > 0:
                            nd = (d+1)%4
                            nr, nc = cr+dirs[nd][0], cc+dirs[nd][1]
                            if 0 <= nr < n and 0 <= nc < m:
                                # parity after consuming current cell
                                p_next = 1 - parity
                                # next cell must match expected for new dir
                                expected = 2 if p_next==0 else 0
                                if grid[nr][nc] == expected:
                                    rem = dp_start[nd][1-p_next][nr][nc]
                                    ans = max(ans, steps + 1 + rem)
                        # move next
                        nr, nc = cr+dr, cc+dc
                        if not (0 <= nr < n and 0 <= nc < m):
                            break
                        expected = 2 if parity==0 else 0
                        if grid[nr][nc] != expected:
                            break
                        cr, cc = nr, nc
                        steps += 1
                        parity = 1 - parity
        return ans
