class Solution:
    def lenOfVDiagonal(self, grid):
        n, m = len(grid), len(grid[0])
        # Directions: TL-BR, BR-TR, TR-BL, BL-TL
        dirs = [(1, 1), (-1, 1), (1, -1), (-1, -1)]
        # dp_len[dir_idx][parity][r][c]  parity: 0 -> expect 2, 1 -> expect 0
        dp_len = [[[ [0]*m for _ in range(n)] for _ in range(2)] for _ in range(4)]
        # compute dp for each dir
        for d, (dr, dc) in enumerate(dirs):
            for parity in (0, 1):
                # traverse in reverse so that next cell already computed
                r_range = range(n-1, -1, -1) if dr>0 else range(n)
                c_range = range(m-1, -1, -1) if dc>0 else range(m)
                for r in r_range:
                    for c in c_range:
                        expected = 2 if parity==0 else 0
                        if grid[r][c]==expected:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<n and 0<=nc<m:
                                dp_len[d][parity][r][c] = 1 + dp_len[d][1-parity][nr][nc]
                            else:
                                dp_len[d][parity][r][c] = 1
                        else:
                            dp_len[d][parity][r][c] = 0
        best = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c]!=1:
                    continue
                for d0, (dr0, dc0) in enumerate(dirs):
                    nr0, nc0 = r+dr0, c+dc0
                    len1 = 1
                    if 0<=nr0<n and 0<=nc0<m:
                        len1 += dp_len[d0][0][nr0][nc0]
                    parity_end = (len1-1)%2
                    best = max(best, len1)
                    # turn to next clockwise dir
                    d1 = (d0+1)%4
                    dr1, dc1 = dirs[d1]
                    nr1, nc1 = r+dr1, c+dc1
                    if 0<=nr1<n and 0<=nc1<m:
                        len2 = len1 + dp_len[d1][parity_end][nr1][nc1]
                        best = max(best, len2)
        return best
