class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n, m = len(skill), len(mana)
        # Initialize 2D array for completion times
        C = [[0] * m for _ in range(n)]
        # First cell
        C[0][0] = skill[0] * mana[0]
        # First row (first wizard)
        for j in range(1, m):
            C[0][j] = C[0][j-1] + skill[0] * mana[j]
        # First column (first potion)
        for i in range(1, n):
            C[i][0] = C[i-1][0] + skill[i] * mana[0]
        # Rest of matrix
        for i in range(1, n):
            for j in range(1, m):
                C[i][j] = max(C[i-1][j], C[i][j-1]) + skill[i] * mana[j]
        return C[n-1][m-1]
