                d = i - j
                diag.setdefault(d, []).append(grid[i][j])
        # sort each diagonal
        for d, values in diag.items():
            if d >= 0:
                values.sort(reverse=True)  # non-increasing
            else:
                values.sort()              # non-decreasing
        # assign back
        res = [[0]*n for _ in range(n)]
        for i in range(n):
