        n = len(grid)
        # collect diagonals by offset (j - i)
        diagonals = {}
        for i in range(n):
            for j in range(n):
                key = j - i
                diagonals.setdefault(key, []).append(grid[i][j])

        # sort each diagonal
        for key, vals in diagonals.items():
            if key >= 0:   # top-right triangle (i < j)
                vals.sort()          # non-decreasing
            else:               # bottom-left triangle (i >= j)
                vals.sort(reverse=True)  # non-increasing

        # write back sorted values
        for i in range(n):
            for j in range(n):
                key = j - i
                grid[i][j] = diagonals[key].pop(0)

