        # Collect diagonals
        diag = {}
        for i in range(n):
            for j in range(n):
                k = i - j
                diag.setdefault(k, []).append(grid[i][j])
        # Sort each diagonal
        for k, vals in diag.items():
            if k >= 0:  # bottom-left triangle (including main diagonal)
                vals.sort(reverse=True)
            else:       # top-right triangle
                vals.sort()
        # Reconstruct grid
        idx = {k:0 for k in diag}
        for i in range(n):
            for j in range(n):
                k = i - j
                grid[i][j] = diag[k][idx[k]]
                idx[k] += 1
        return grid
