import sys

MOD = 998244353

def modpow(a, e):
    res = 1
    while e:
        if e & 1:
            res = res * a % MOD
        a = a * a % MOD
        e >>= 1
    return res

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0]); M = int(data[1]); S = data[2]
    max_n = max(N, M)
    fact = [1] * (max_n + 1)
    invfact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD
    invfact[max_n] = modpow(fact[max_n], MOD-2)
    for i in range(max_n, 0, -1):
        invfact[i-1] = invfact[i] * i % MOD
    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

    pow26 = [1]*(M+1)
    for i in range(1, M+1):
        pow26[i] = pow26[i-1]*26 % MOD

    g = [0]*(N+1)
    for L in range(0, N+1):
        if L > M:
            break
        g[L] = C(N, L) * C(M, L) % MOD * pow26[M-L] % MOD

    h = [0]*(N+1)
    for L in range(N, -1, -1):
        val = g[L]
        for i in range(L+1, N+1):
            val = (val - h[i] * C(i, L)) % MOD
        h[L] = val % MOD

    print(' '.join(str(h[i]%MOD) for i in range(N+1)))

if __name__ == "__main__":
    solve()
