class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        forced = ['?'] * L

        # Apply T constraints
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    if forced[pos] != '?' and forced[pos] != str2[j]:
                        return ""
                    forced[pos] = str2[j]

        # Prepare F windows
        f_windows = []
        start_of = []  # start index of each window
        for i, ch in enumerate(str1):
            if ch == 'F':
                f_windows.append([0, 0])  # [cnt_free, same_count]
                start_of.append(i)
        wcnt = len(f_windows)
        pos_to_wins = [[] for _ in range(L)]
        for wi, s in enumerate(start_of):
            for j in range(m):
                pos = s + j
                pos_to_wins[pos].append(wi)

        # Initialize counters
        for wi, s in enumerate(start_of):
            cnt_free = 0
            same = 0
            for j in range(m):
                pos = s + j
                if forced[pos] == '?':
                    cnt_free += 1
                else:
                    if forced[pos] == str2[j]:
                        same += 1
            f_windows[wi][0] = cnt_free
            f_windows[wi][1] = same

        # Check existing windows for impossibility
        for wi, (cnt_free, same) in enumerate(f_windows):
            if cnt_free == 0 and same == m:
                return ""

        # Build answer greedily
        for p in range(L):
            if forced[p] != '?':
                # Update windows
                for wi in pos_to_wins[p]:
                    f_windows[wi][0] -= 1
                    if forced[p] == str2[p - start_of[wi]]:
                        f_windows[wi][1] += 1
                # Verify
                for wi in pos_to_wins[p]:
                    cnt_free, same = f_windows[wi]
                    if cnt_free == 0 and same == m:
                        return ""
                continue

            # Try letters
            chosen = None
            for c in map(chr, range(ord('a'), ord('z') + 1)):
                ok = True
                for wi in pos_to_wins[p]:
                    cnt_free, same = f_windows[wi]
                    new_cnt = cnt_free - 1
                    new_same = same + (c == str2[p - start_of[wi]])
                    if new_cnt == 0 and new_same == m:
                        ok = False
                        break
                if ok:
                    chosen = c
                    break
            if chosen is None:
                return ""
            forced[p] = chosen
            for wi in pos_to_wins[p]:
                f_windows[wi][0] -= 1
                if chosen == str2[p - start_of[wi]]:
                    f_windows[wi][1] += 1

        return ''.join(forced)
