class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        res = [None] * L

        # Apply 'T' constraints
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    if res[pos] is None:
                        res[pos] = str2[j]
                    elif res[pos] != str2[j]:
                        return ""

        # Prepare F substrings info
        f_indices = []  # list of (start, list of offset)
        f_pos_map = [[] for _ in range(L)]  # pos -> list of f idx
        for i, ch in enumerate(str1):
            if ch == 'F':
                offsets = list(range(m))
                f_indices.append((i, offsets))
                fid = len(f_indices) - 1
                for j in offsets:
                    f_pos_map[i + j].append(fid)

        f_unassigned = [0] * len(f_indices)
        f_equal = [0] * len(f_indices)
        # initialize counts
        for fid, (start, offsets) in enumerate(f_indices):
            uc = 0
            ec = 0
            for j in offsets:
                pos = start + j
                if res[pos] is None:
                    uc += 1
                else:
                    if res[pos] == str2[j]:
                        ec += 1
            f_unassigned[fid] = uc
            f_equal[fid] = ec

        # Greedy assignment
        for pos in range(L):
            if res[pos] is not None:
                continue
            for c_ord in range(ord('a'), ord('z') + 1):
                c = chr(c_ord)
                ok = True
                for fid in f_pos_map[pos]:
                    start, offsets = f_indices[fid]
                    j = pos - start
                    new_uc = f_unassigned[fid] - 1
                    add_eq = 1 if c == str2[j] else 0
                    new_ec = f_equal[fid] + add_eq
                    if new_uc == 0 and new_ec == m:
                        ok = False
                        break
                if ok:
                    res[pos] = c
                    for fid in f_pos_map[pos]:
                        start, offsets = f_indices[fid]
                        j = pos - start
                        if c == str2[j]:
                            f_equal[fid] += 1
                        f_unassigned[fid] -= 1
                    break
            if res[pos] is None:
                return ""

        # fill remaining positions with 'a'
        for i in range(L):
            if res[i] is None:
                res[i] = 'a'
        return "".join(res)
