class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        # initialize result with None
        res = [None] * L
        # constraints for 'T'
        for i, c in enumerate(str1):
            if c == 'T':
                for j in range(m):
                    pos = i + j
                    ch = str2[j]
                    if res[pos] is not None and res[pos] != ch:
                        return ""
                    res[pos] = ch
        # Prepare F windows
        f_windows = []
        for i, c in enumerate(str1):
            if c == 'F':
                f_windows.append((i, set(str2)))
        # For each position, list windows covering it
        pos_windows = [[] for _ in range(L)]
        for idx, (start, _) in enumerate(f_windows):
            for p in range(start, start + m):
                pos_windows[p].append(idx)
        # Track state for each window
        win_unassigned = [m] * len(f_windows)
        win_diff = [False] * len(f_windows)
        # Assign characters greedily
        for p in range(L):
            # Determine required char if any
            req = res[p]
            # Determine minimal char to use
            def choose_char():
                if req is not None:
                    return req
                # try 'a' first
                for ch in 'abcdefghijklmnopqrstuvwxyz':
                    # check if setting ch would violate any window
                    bad = False
                    for wi in pos_windows[p]:
                        start, _ = f_windows[wi]
                        idx_in_win = p - start
                        # if ch matches required and all others already matched
                        if ch == str2[idx_in_win]:
                            # check if all other positions already matched
                            if win_unassigned[wi] == 1 and not win_diff[wi]:
                                bad = True
                                break
                    if not bad:
                        return ch
                return 'z'
            ch = choose_char()
            res[p] = ch
            # update windows
            for wi in pos_windows[p]:
                win_unassigned[wi] -= 1
                start, _ = f_windows[wi]
                idx_in_win = p - start
                if ch != str2[idx_in_win]:
                    win_diff[wi] = True
                if win_unassigned[wi] == 0 and not win_diff[wi]:
                    return ""
        return "".join(res)
