class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = ['?'] * L
        constrained = [False] * L  # True if set by a 'T' constraint

        # Apply 'T' constraints
        for i, flag in enumerate(str1):
            if flag == 'T':
                for j in range(m):
                    pos = i + j
                    c = str2[j]
                    if word[pos] == '?':
                        word[pos] = c
                        constrained[pos] = True
                    elif word[pos] != c:
                        return ""

        # Fill remaining with 'a'
        for i in range(L):
            if word[i] == '?':
                word[i] = 'a'

        # Resolve 'F' constraints
        for i, flag in enumerate(str1):
            if flag == 'F':
                # Check if substring equals str2
                equal = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        equal = False
                        break
                if not equal:
                    continue
                # Need to modify
                modified = False
                for j in range(m):
                    pos = i + j
                    if constrained[pos]:
                        continue
                    # choose smallest char different from str2[j]
                    for ch in 'abcdefghijklmnopqrstuvwxyz':
                        if ch != str2[j]:
                            word[pos] = ch
                            modified = True
                            break
                    if modified:
                        break
                if not modified:
                    return ""

        return ''.join(word)
