        n = len(startTime)
        durations = [endTime[i] - startTime[i] for i in range(n)]
        totalDur = sum(durations)
        durations.sort(reverse=True)
        sumK = sum(durations[:k])
        return max(0, eventTime - totalDur + sumK)
