class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        INF = 10**15
        # dp[l][k] = (cost, prev_state, prev_pos, prev_k)
        dp = [[[INF, None, None, None] for _ in range(3)] for _ in range(26)]
        # start
        for t in range(26):
            cost = abs(ord(caption[0]) - (ord('a') + t))
            dp[t][1][0] = (cost, None, None, None)  # len=1

        for i in range(1, n):
            new_dp = [[[INF, None, None, None] for _ in range(3)] for _ in range(26)]
            ci = ord(caption[i]) - 97
            for l in range(26):
                for k in range(3):
                    cur_cost, _, _, _ = dp[l][k]
                    if cur_cost >= INF: continue
                    for t in range(26):
                        add = abs(ci - t)
                        if t == l:
                            nk = min(k + 1, 2)
                            if cur_cost + add < new_dp[t][nk][0]:
                                new_dp[t][nk] = (cur_cost + add, l, i-1, k)
                        else:
                            if k == 2:  # can switch
                                nk = 1
                                if cur_cost + add < new_dp[t][nk][0]:
                                    new_dp[t][nk] = (cur_cost + add, l, i-1, k)
            dp = new_dp

        # find best ending with k==2 (i.e., run length >=3)
        best_cost = INF
        best_state = None
        for l in range(26):
            cost, *_ = dp[l][2]
            if cost < best_cost:
                best_cost = cost
                best_state = (l, 2, n-1)
        if best_cost >= INF:
            return ""

        # reconstruct
        res = [''] * n
        l, k, pos = best_state
        while pos is not None:
            res[pos] = chr(ord('a') + l)
            cost, prev_l, prev_pos, prev_k = dp[l][k]
            l, k, pos = prev_l, prev_k, prev_pos
        return ''.join(res)
