class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        INF = 10**18
        # map char to int
        a_ord = ord('a')
        orig = [ord(c) - a_ord for c in caption]
        # dp[pos][prev_char][run_len] -> min cost from pos to end
        # prev_char: 0..25, 26 means none
        dp = [[[INF]*4 for _ in range(27)] for __ in range(n+1)]
        # base
        for prev in range(27):
            for rl in range(1,4):
                dp[n][prev][rl] = 0 if rl>=3 else INF
        # backward DP
        for pos in range(n-1, -1, -1):
            cur = orig[pos]
            for prev in range(27):
                for rl in range(1,4):
                    best = INF
                    for new in range(26):
                        if prev == 26:  # first char
                            new_len = 1
                        else:
                            if new == prev:
                                new_len = min(rl+1,3)
                            else:
                                if rl < 3:
                                    continue
                                new_len = 1
                        cost = abs(new - cur) + dp[pos+1][new][new_len]
                        if cost < best:
                            best = cost
                    dp[pos][prev][rl] = best
        # find minimal total cost at start
        best_total = INF
        best_first = None
        for first in range(26):
            total = abs(first - orig[0]) + dp[1][first][1]
            if total < best_total:
                best_total = total
                best_first = first
        if best_total >= INF:
            return ""
        # reconstruct lexicographically smallest
        res_chars = []
        prev = 26
        rl = 1
        cur = orig[0]
        total_cost = best_total
        for pos in range(n):
            cur = orig[pos]
            chosen = None
            for new in range(26):
                if prev == 26:
                    new_len = 1
                else:
                    if new == prev:
                        new_len = min(rl+1,3)
                    else:
                        if rl < 3:
                            continue
                        new_len = 1
                cost = abs(new - cur) + dp[pos+1][new][new_len]
                if cost == total_cost:
                    chosen = new
                    break
            if chosen is None:
                return ""
            res_chars.append(chr(chosen + a_ord))
            total_cost -= abs(chosen - cur)
            prev = chosen
            if prev == 26:
                rl = 1
            else:
                rl = new_len
        return "".join(res_chars)
