class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        INF = 10**9
        # dp[i][c][l] = min cost up to position i-1 with last letter c (0-25) and current run length l (0-2)
        dp = [[[INF]*3 for _ in range(26)] for _ in range(n+1)]
        # parent pointers for reconstruction
        parent = [[[-1]*3 for _ in range(26)] for _ in range(n+1)]
        choice = [[['']*3 for _ in range(26)] for _ in range(n+1)]
        # start
        for c in range(26):
            ch = chr(c+97)
            if ch == caption[0]:
                cost = 0
            elif ch == chr(c+98) or ch == chr(c+96):
                cost = 1
            else:
                continue
            dp[1][c][1] = cost
            parent[1][c][1] = -1
            choice[1][c][1] = ch
        # process
        for i in range(1, n):
            for lc in range(26):
                for l in range(1,3):
                    if dp[i][lc][l] >= INF:
                        continue
                    for nc in range(26):
                        ch = chr(nc+97)
                        if ch == caption[i]:
                            cost = dp[i][lc][l]
                        elif ch == chr(nc+98) or ch == chr(nc+96):
                            cost = dp[i][lc][l] + 1
                        else:
                            continue
                        if nc == lc:
                            nl = l+1
                            if nl > 2:
                                nl = 0
                        else:
                            nl = 1
                        if cost < dp[i+1][nc][nl]:
                            dp[i+1][nc][nl] = cost
                            parent[i+1][nc][nl] = (lc, l)
                            choice[i+1][nc][nl] = ch
                        elif cost == dp[i+1][nc][nl]:
                            # tie-breaking by lexicographic
                            prev_lc, prev_l = parent[i+1][nc][nl]
                            prev_str = []
                            # build previous string
                            j = i+1
                            while j > 0 and prev_lc != -1:
                                prev_str.append(choice[j][prev_lc][prev_l])
                                prev_lc, prev_l = parent[j][prev_lc][prev_l]
                                j -= 1
                            prev_str = ''.join(reversed(prev_str))
                            new_prev_str = prev_str + ch
                            if new_prev_str < prev_str:
                                parent[i+1][nc][nl] = (lc, l)
                                choice[i+1][nc][nl] = ch
        # find best ending state
        best = INF
        best_state = None
        for c in range(26):
            for l in range(1,3):
                if dp[n][c][l] < best:
                    best = dp[n][c][l]
                    best_state = (c, l)
        if best_state is None:
            return ""
        # reconstruct
        res = []
        i = n
        c, l = best_state
        while i > 0:
            res.append(choice[i][c][l])
            c, l = parent[i][c][l]
            i -= 1
        return ''.join(reversed(res))
