class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        from functools import lru_cache
        n = len(caption)
        INF = 10**9

        # precompute possible chars at each position
        options = []
        for ch in caption:
            lst = [ch]
            if ch > 'a':
                lst.append(chr(ord(ch)-1))
            if ch < 'z':
                lst.append(chr(ord(ch)+1))
            options.append(sorted(set(lst)))  # sorted for lex order

        @lru_cache(maxsize=None)
        def dp(pos, last_char, run_len):
            if pos == n:
                return 0 if run_len == 0 or run_len >= 3 else INF
            best = INF
            for ch in options[pos]:
                inc = 0 if ch == caption[pos] else 1
                if last_char == -1:
                    new_len = 1
                elif ch == last_char:
                    new_len = 3 if run_len + 1 >= 3 else run_len + 1
                else:
                    if run_len < 3:
                        continue
                    new_len = 1
                val = inc + dp(pos+1, ch, new_len)
                if val < best:
                    best = val
            return best

        min_cost = dp(0, -1, 0)
        if min_cost >= INF:
            return ""

        # reconstruct lexicographically smallest
        res = []
        pos, last_char, run_len = 0, -1, 0
        while pos < n:
            for ch in options[pos]:
                inc = 0 if ch == caption[pos] else 1
                if last_char == -1:
                    new_len = 1
                elif ch == last_char:
                    new_len = 3 if run_len + 1 >= 3 else run_len + 1
                else:
                    if run_len < 3:
                        continue
                    new_len = 1
                if inc + dp(pos+1, ch, new_len) == min_cost:
                    res.append(ch)
                    pos += 1
                    last_char, run_len = ch, new_len
                    min_cost -= inc
                    break
        return "".join(res)
