import sys
from collections import deque

def solve() -> None:
    it = iter(sys.stdin.read().splitlines())
    N = int(next(it))
    g = [[c for c in line.strip()] for line in it]
    # adjacency list: for each node, list of (neighbor, label)
    adj = [[] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            c = g[i][j]
            if c != '-':
                adj[i].append((j, c))
    # Precompute edges existence for odd length check
    has_edge = [[False]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if g[i][j] != '-':
                has_edge[i][j] = True
    res = [[-1]*N for _ in range(N)]
    for src in range(N):
        for dst in range(N):
            if src == dst:
                res[src][dst] = 0
                continue
            # BFS
            dist = [[-1]*N for _ in range(N)]
            dq = deque()
            dist[src][dst] = 0
            dq.append((src, dst))
            ans = -1
            while dq:
                u, v = dq.popleft()
                d = dist[u][v]
                # check finish
                if u == v:
                    ans = d*2
                    break
                if has_edge[u][v]:
                    ans = d*2 + 1
                    break
                # transitions
                neigh_u = adj[u]
                neigh_v = adj[v]
                # for each label match
                for uu, cu in neigh_u:
                    for vv, cv in neigh_v:
                        if cu == cv and dist[uu][vv] == -1:
                            dist[uu][vv] = d + 1
                            dq.append((uu, vv))
            res[src][dst] = ans
    out_lines = []
    for row in res:
        out_lines.append(' '.join(str(x) for x in row))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()
