import sys
from collections import deque

def main():
    data = sys.stdin.read().splitlines()
    N = int(data[0])
    mat = data[1:]
    # build outgoing edges per node per label
    out = [{} for _ in range(N)]  # dict label -> list of targets
    for i in range(N):
        row = mat[i]
        d = {}
        for j, ch in enumerate(row):
            if ch != '-':
                d.setdefault(ch, []).append(j)
        out[i] = d

    total = N * N
    rev_adj = [[] for _ in range(total)]
    sources = []

    for u in range(N):
        for v in range(N):
            idx = u * N + v
            # center odd
            if u == v:
                sources.append(idx)
            # center even: mutual edge with same label
            for c, lst_u in out[u].items():
                if c in out[v]:
                    for x in lst_u:
                        for y in out[v][c]:
                            if x == v and y == u:
                                # mutual edge found
                                sources.append(idx)
                                break
                        else:
                            continue
                        break
            # build transitions
            for c, lst_u in out[u].items():
                if c in out[v]:
                    lst_v = out[v][c]
                    for x in lst_u:
                        for y in lst_v:
                            to_idx = x * N + y
                            rev_adj[to_idx].append(idx)

    # BFS reversed
    dist = [-1] * total
    dq = deque()
    for s in sources:
        dist[s] = 0
        dq.append(s)
    while dq:
        cur = dq.popleft()
        dcur = dist[cur]
        for pre in rev_adj[cur]:
            if dist[pre] == -1:
                dist[pre] = dcur + 1
                dq.append(pre)

    out_lines = []
    for i in range(N):
        row = []
        for j in range(N):
            val = dist[i * N + j]
            row.append(str(val))
        out_lines.append(' '.join(row))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    main()
