import sys
from collections import deque

def main():
    it = iter(sys.stdin.read().splitlines())
    N = int(next(it))
    graph = [[] for _ in range(N)]
    for i in range(N):
        line = next(it).strip()
        for j, ch in enumerate(line):
            if ch != '-':
                graph[i].append((j, ch))

    INF = 10**9
    dist = [[INF]*N for _ in range(N)]
    q = deque()

    # start with length 0 (i==j)
    for i in range(N):
        dist[i][i] = 0
        q.append((i,i))

    # start with length 1 (direct edge)
    for u in range(N):
        for v,ch in graph[u]:
            if dist[u][v] > 1:
                dist[u][v] = 1
                q.append((u,v))

    # BFS
    while q:
        a,b = q.popleft()
        da = dist[a][b]
        # extend by 2
        for a2, ca in graph[a]:
            for b2, cb in graph[b]:
                if ca == cb and dist[a2][b2] > da + 2:
                    dist[a2][b2] = da + 2
                    q.append((a2,b2))

    out_lines = []
    for i in range(N):
        row = []
        for j in range(N):
            val = dist[i][j]
            row.append(str(val if val != INF else -1))
        out_lines.append(' '.join(row))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    main()
