from math import gcd
from typing import List

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        n = len(nums)
        m = len(target)
        full = 1 << m
        INF = 10**18

        # precompute lcm for all subsets
        lcm_subset = [1] * full
        for mask in range(1, full):
            l = 1
            for i in range(m):
                if mask >> i & 1:
                    l = l * target[i] // gcd(l, target[i])
                    if l > 10**9:
                        l = 10**9 + 1
                        break
            lcm_subset[mask] = l

        # cost[i][mask] for each nums element
        cost = [[INF]*full for _ in range(n)]
        for idx, val in enumerate(nums):
            cost[idx][0] = 0
            for mask in range(1, full):
                l = lcm_subset[mask]
                if l > 10**9:
                    continue
                r = val % l
                cost[idx][mask] = (l - r) % l

        dp = [INF]*full
        dp[0] = 0
        for idx in range(n):
            c = cost[idx]
            new_dp = dp[:]
            for mask in range(full):
                if dp[mask] == INF:
                    continue
                remaining = full - 1 - mask
                sub = remaining
                while sub:
                    if c[sub] < INF:
                        nm = mask | sub
                        if new_dp[nm] > dp[mask] + c[sub]:
                            new_dp[nm] = dp[mask] + c[sub]
                    sub = (sub - 1) & remaining
            dp = new_dp
        return dp[full-1]
