from typing import List
import math

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        tlen = len(target)
        full_mask = (1 << tlen) - 1
        # Precompute lcm for all subsets
        lcm_subset = [1] * (1 << tlen)
        for mask in range(1, 1 << tlen):
            l = 1
            for i in range(tlen):
                if mask & (1 << i):
                    l = l * target[i] // math.gcd(l, target[i])
            lcm_subset[mask] = l

        # Precompute cost for each element and subset
        costs = [[0] * (1 << tlen) for _ in nums]
        for idx, val in enumerate(nums):
            for mask in range(1, 1 << tlen):
                l = lcm_subset[mask]
                rem = val % l
                if rem == 0:
                    inc = 0
                else:
                    inc = l - rem
                costs[idx][mask] = inc

        INF = 10**18
        dp = [INF] * (1 << tlen)
        dp[0] = 0
        for idx in range(len(nums)):
            new_dp = dp[:]
            for mask in range(1 << tlen):
                if dp[mask] == INF:
                    continue
                # try all subsets that are disjoint from mask
                sub = full_mask ^ mask
                submask = sub
                while submask:
                    cost = costs[idx][submask]
                    new_mask = mask | submask
                    if new_dp[new_mask] > dp[mask] + cost:
                        new_dp[new_mask] = dp[mask] + cost
                    submask = (submask - 1) & sub
            dp = new_dp
        return dp[full_mask]
