    # function to merge intervals
    def merge_intervals(ints):
        if not ints:
            return []
        ints.sort()
        res = [ints[0]]
        for l, r in ints[1:]:
            if l <= res[-1][1]+1:
                res[-1] = (res[-1][0], max(res[-1][1], r))
            else:
                res.append((l, r))
        return res
    # iterate until no change
    while True:
        new_reach = []
        for l, r in reach:
            new_l = l + A
            new_r = r + B
            if new_l > N:
                continue
            if new_r > N:
                new_r = N
            new_reach.append((new_l, new_r))
        new_reach = merge_intervals(new_reach)
        # intersect with good intervals
        inter = []
        i = j = 0
        while i < len(new_reach) and j < len(good):
            l1, r1 = new_reach[i]
            l2, r2 = good[j]
            if r1 < l2:
                i += 1
            elif r2 < l1:
