import sys
import threading
def solve():
    import sys
    sys.setrecursionlimit(1 << 25)
    H, W = map(int, sys.stdin.readline().split())
    N = H * W
    F = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]
    def idx(i, j):
        return i * W + j
    edges = []
    for i in range(H):
        for j in range(W):
            u = idx(i, j)
            if i + 1 < H:
                v = idx(i + 1, j)
                w = min(F[i][j], F[i + 1][j])
                edges.append((w, u, v))
            if j + 1 < W:
                v = idx(i, j + 1)
                w = min(F[i][j], F[i][j + 1])
                edges.append((w, u, v))
    edges.sort(reverse=True)
    parent = list(range(N))
    rank = [0] * N
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        x = find(x); y = find(y)
        if x == y: return False
        if rank[x] < rank[y]:
            parent[x] = y
        else:
            parent[y] = x
            if rank[x] == rank[y]:
                rank[x] += 1
        return True
    tree = [[] for _ in range(N)]
    for w, u, v in edges:
        if union(u, v):
            tree[u].append((v, w))
            tree[v].append((u, w))
    LOG = (N-1).bit_length()
    up = [[-1]*N for _ in range(LOG)]
    minw = [[10**9]*N for _ in range(LOG)]
    depth = [0]*N
    def dfs(v, p):
        for to, w in tree[v]:
            if to==p: continue
            depth[to]=depth[v]+1
            up[0][to]=v
            minw[0][to]=w
            dfs(to, v)
    dfs(0, -1)
    for k in range(1, LOG):
        for v in range(N):
            if up[k-1][v] != -1:
                up[k][v] = up[k-1][up[k-1][v]]
                minw[k][v] = min(minw[k-1][v], minw[k-1][up[k-1][v]])
    def query_bottleneck(a, b):
        if a==b: return F[a//W][a%W]
        if depth[a] < depth[b]:
            a, b = b, a
        diff = depth[a]-depth[b]
        best = 10**9
        for k in range(LOG):
            if diff>>k & 1:
                best = min(best, minw[k][a])
                a = up[k][a]
        if a==b:
            return best
        for k in range(LOG-1, -1, -1):
            if up[k][a]!=-1 and up[k][a]!=up[k][b]:
                best = min(best, minw[k][a], minw[k][b])
                a=up[k][a]
                b=up[k][b]
        best = min(best, minw[0][a], minw[0][b])
        return best
    Q = int(sys.stdin.readline())
    out_lines = []
    for _ in range(Q):
        A,B,Y,C,D,Z = map(int, sys.stdin.readline().split())
        a = idx(A-1,B-1)
        c = idx(C-1,D-1)
        bottleneck = query_bottleneck(a, c)
        maxF = bottleneck
        if maxF >= max(Y, Z):
            ans = abs(Y-Z)
        else:
            if maxF <= min(Y, Z):
                ans = Y + Z - 2*maxF
            else:
                ans = abs(Y-Z) + (max(Y,Z)-maxF)
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

threading.Thread(target=solve).start()
```

