    if not data:
        return
    it = iter(data)
    n = int(next(it))
    P = [int(next(it)) for _ in range(n)]

    class BIT:
        def __init__(self, n):
            self.n = n
            self.bit = [0]*(n+1)
        def add(self, idx, val):
            while idx <= self.n:
                self.bit[idx] += val
                idx += idx & -idx
        def sum(self, idx):
            s = 0
            while idx:
                s += self.bit[idx]
                idx -= idx & -idx
            return s
        def kth(self, k):
            idx = 0
            bit_mask = 1 << (self.n.bit_length())
            while bit_mask:
                t = idx + bit_mask
                if t <= self.n and self.bit[t] < k:
                    idx = t
                    k -= self.bit[t]
                bit_mask >>= 1
            return idx + 1

    bit = BIT(n)
    for i in range(1, n+1):
        bit.add(i, 1)  # all positions initially empty

    res = [0]*n
    for i in range(n, 0, -1):
        k = P[i-1]
        pos = bit.kth(k)
        res[pos-1] = i
        bit.add(pos, -1)

    print(' '.join(map(str, res)))

