import sys
import random
sys.setrecursionlimit(1 << 25)

class Node:
    __slots__ = ('val','prio','size','l','r')
    def __init__(self, val):
        self.val = val
        self.prio = random.randint(1, 1 << 30)
        self.size = 1
        self.l = None
        self.r = None

def upd(t):
    if t:
        t.size = 1 + (t.l.size if t.l else 0) + (t.r.size if t.r else 0)

def split(t, k):
    if not t:
        return (None, None)
    if (t.l.size if t.l else 0) >= k:
        left, right = split(t.l, k)
        t.l = right
        upd(t)
        return (left, t)
    else:
        left, right = split(t.r, k - (t.l.size if t.l else 0) - 1)
        t.r = left
        upd(t)
        return (t, right)

def merge(a, b):
    if not a or not b:
        return a or b
    if a.prio > b.prio:
        a.r = merge(a.r, b)
        upd(a)
        return a
    else:
        b.l = merge(a, b.l)
        upd(b)
        return b

def inorder(t, res):
    if t:
        inorder(t.l, res)
        res.append(t.val)
        inorder(t.r, res)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    P = [int(next(it)) for _ in range(N)]
    root = None
    for i in range(1, N+1):
        pos = P[i-1]-1  # 0-indexed
        left, right = split(root, pos)
        node = Node(i)
        root = merge(merge(left, node), right)
    res = []
    inorder(root, res)
    print(' '.join(map(str, res)))

if __name__ == "__main__":
    main()
