class Solution:
    def separateSquares(self, squares: list[list[int]]) -> float:
        total_area = 0
        min_y = float('inf')
        max_y = 0
        for x, y, l in squares:
            total_area += l * l
            if y < min_y:
                min_y = y
            if y + l > max_y:
                max_y = y + l

        def above(y0: float) -> float:
            area = 0.0
            for x, y, l in squares:
                top = y + l
                if y0 <= y:
                    area += l * l
                elif y0 < top:
                    area += (top - y0) * l
            return area

        lo, hi = min_y, max_y
        for _ in range(80):  # sufficient for 1e-5 precision
            mid = (lo + hi) / 2
            if 2 * above(mid) - total_area > 0:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2
