from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0
        extra = m - n

        def feasible(S: int) -> bool:
            need = 0
            for p in points:
                if S > p:
                    need += (S - p + p - 1) // p
                    if need > extra:
                        return False
            return need <= extra

        low, high = 0, max(points) * (m // n + 1)  # upper bound
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1
        return low
