                    best_idx = h[0]
        if best_idx is None:
            best_idx = N
        # replace
        old = cur[best_idx-1]
        if old == c:
            # nothing changes but still push for consistency
            pass
        else:
            cur[best_idx-1] = c
            heapq.heappush(heaps[c], best_idx)

    print(''.join(str(d) for d in cur))

