class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # sets of achievable sums for each index
        achievable = [set([0]) for _ in range(n)]
        for k, (l, r, val) in enumerate(queries, 1):
            # update indices in range
            for i in range(l, r + 1):
                new_set = set()
                for s in achievable[i]:
                    new_set.add(s)
                    new_set.add(s + val)
                achievable[i] = new_set
            # check if all target sums reachable
            if all(nums[i] in achievable[i] for i in range(n)):
                return k
        return -1
