class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        max_sum = max(nums)
        # dp[i] is a bitset of achievable sums for index i
        dp = [1 << 0] * n  # only sum 0 achievable initially
        for k, (l, r, val) in enumerate(queries, 1):
            mask = (1 << (max_sum + 1)) - 1  # keep bits up to max_sum
            for i in range(l, r + 1):
                dp[i] = (dp[i] | (dp[i] << val)) & mask
            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k
        return -1
