class Solution:
    def minZeroArray(self, nums, queries):
        n = len(nums)
        m = len(queries)
        target = max(nums) if nums else 0
        # Precompute which queries cover each index
        cover = [[] for _ in range(n)]
        for idx, (l, r, val) in enumerate(queries):
            for i in range(l, r + 1):
                cover[i].append((idx, val))
        def possible(k):
            for i in range(n):
                bitset = 1  # bit 0 set
                for idx, val in cover[i]:
                    if idx >= k: break
                    bitset |= (bitset << val)
                if not (bitset >> nums[i]) & 1:
                    return False
            return True
        lo, hi = 1, m + 1
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if possible(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans if ans != -1 else -1
