        m, n = len(coins), len(coins[0])
        NEG = -10**18
        # dp_prev[j][k] for previous row
        dp_prev = [[NEG]*3 for _ in range(n)]
        for i in range(m):
            dp_cur = [[NEG]*3 for _ in range(n)]
            for j in range(n):
                for k in range(3):
                    best = NEG
                    # from top
                    if i > 0:
                        best = max(best, dp_prev[j][k])
                    # from left
                    if j > 0:
                        best = max(best, dp_cur[j-1][k])
                    # from start cell
                    if i == 0 and j == 0:
                        best = 0
                    if best == NEG:
                        continue
                    val = coins[i][j]
                    if val >= 0:
                        cand = best + val
                        if cand > dp_cur[j][k]:
                            dp_cur[j][k] = cand
                    else:
                        # not neutralize
                        cand = best + val
                        if cand > dp_cur[j][k]:
                            dp_cur[j][k] = cand
                        # neutralize if allowed
                        if k < 2:
                            cand = best
                            if cand > dp_cur[j][k+1]:
                                dp_cur[j][k+1] = cand
            dp_prev = dp_cur
        return max(max(row) for row in dp_prev)
