class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG = -10**18
        dp = [[[NEG] * 3 for _ in range(n)] for _ in range(m)]
        # start cell
        val = coins[0][0]
        if val >= 0:
            dp[0][0][0] = val
            if n > 1 or m > 1:
                dp[0][0][1] = val  # neutralize unused
        else:
            dp[0][0][0] = val
            dp[0][0][1] = 0  # neutralize this cell
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                for k in range(3):
                    best = NEG
                    if i > 0:
                        best = max(best, dp[i-1][j][k])
                    if j > 0:
                        best = max(best, dp[i][j-1][k])
                    if best == NEG:
                        continue
                    val = coins[i][j]
                    if val >= 0:
                        dp[i][j][k] = best + val
                    else:
                        dp[i][j][k] = best + val
                        if k < 2:
                            dp[i][j][k+1] = max(dp[i][j][k+1], best)
        return max(max(row) for row in dp)
