class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        maxd = 0
        x = y = 0
        for ch in s:
            if ch == 'N':
                y += 1
            elif ch == 'S':
                y -= 1
            elif ch == 'E':
                x += 1
            else:  # 'W'
                x -= 1
            # compute best distance with at most k changes
            # we can change up to k steps that reduce distance
            # count steps that are opposite to the sign of current x,y
            badx = 0
            if x > 0:
                badx = s[:s.index(ch)+1].count('W')
            elif x < 0:
                badx = s[:s.index(ch)+1].count('E')
            bady = 0
            if y > 0:
                bady = s[:s.index(ch)+1].count('S')
            elif y < 0:
                bady = s[:s.index(ch)+1].count('N')
            can_use = min(k, badx + bady)
            dist = abs(x) + abs(y) + 2 * can_use
            maxd = max(maxd, dist)
        return maxd
