class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        x = y = 0
        maxd = 0
        changes = k
        for ch in s:
            best_delta = -1
            best_move = ch
            # try all 4 directions
            for d in ('N','S','E','W'):
                nx, ny = x, y
                if d == 'N':
                    ny += 1
                elif d == 'S':
                    ny -= 1
                elif d == 'E':
                    nx += 1
                else:  # 'W'
                    nx -= 1
                delta = abs(nx) + abs(ny) - (abs(x) + abs(y))
                if delta > best_delta:
                    best_delta = delta
                    best_move = d
            # decide to use change if beneficial and we have changes left
            if best_move != ch and changes > 0:
                ch = best_move
                changes -= 1
            # apply move
            if ch == 'N':
                y += 1
            elif ch == 'S':
                y -= 1
            elif ch == 'E':
                x += 1
            else:  # 'W'
                x -= 1
            maxd = max(maxd, abs(x) + abs(y))
        return maxd
