    for t in range(3):
        dp[t][0] = 0
        for cost, val in items[t]:
            for c in range(X, cost - 1, -1):
                if dp[t][c - cost] + val > dp[t][c]:
                    dp[t][c] = dp[t][c - cost] + val
        # prefix max to allow <= calories
        for c in range(1, X + 1):
            if dp[t][c - 1] > dp[t][c]:
                dp[t][c] = dp[t][c - 1]

