class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True
        first = [-1]*26
        last = [-1]*26
        for i,ch in enumerate(s):
            idx = ord(ch)-97
            if first[idx]==-1:
                first[idx]=i
            last[idx]=i
        res = 0
        i = 0
        while i < n:
            cur_start = i
            cur_end = last[ord(s[i])-97]
            j = i
            while j <= cur_end:
                cidx = ord(s[j])-97
                cur_end = max(cur_end, last[cidx])
                j += 1
            if cur_start==0 and cur_end==n-1:
                # whole string cannot be used
                pass
            else:
                res += 1
                if res >= k:
                    return True
            i = cur_end + 1
        return False
