class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True
        first = [-1] * 26
        last = [-1] * 26
        for i, ch in enumerate(s):
            idx = ord(ch) - 97
            if first[idx] == -1:
                first[idx] = i
            last[idx] = i

        seg_count = 0
        i = 0
        while i < n:
            max_right = last[ord(s[i]) - 97]
            j = i
            while j < max_right:
                j += 1
                c = ord(s[j]) - 97
                if last[c] > max_right:
                    max_right = last[c]
            # segment [i, max_right]
            if not (i == 0 and max_right == n - 1):
                seg_count += 1
            i = max_right + 1

        return seg_count >= k
