class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True
        left = {}
        right = {}
        for i, ch in enumerate(s):
            if ch not in left:
                left[ch] = i
            right[ch] = i
        # compute minimal segment for each character
        segs = []
        for ch in left:
            l = left[ch]
            r = right[ch]
            changed = True
            while changed:
                changed = False
                i = l
                while i <= r:
                    c = s[i]
                    if left[c] < l or right[c] > r:
                        l = min(l, left[c])
                        r = max(r, right[c])
                        changed = True
                    i += 1
            if l == 0 and r == n-1:
                continue
            segs.append((l, r))
        # remove duplicates
        segs = list(set(segs))
        segs.sort(key=lambda x: x[1])
        count = 0
        last_end = -1
        for l, r in segs:
            if l > last_end:
                count += 1
                last_end = r
                if count >= k:
                    return True
        return False
