class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True
        first = {}
        last = {}
        for i, ch in enumerate(s):
            if ch not in first:
                first[ch] = i
            last[ch] = i
        substrings = []
        i = 0
        while i < n:
            end = last[s[i]]
            j = i + 1
            while j <= end:
                end = max(end, last[s[j]])
                j += 1
            # skip if the substring is the whole string
            if not (i == 0 and end == n - 1):
                substrings.append((i, end))
            i = end + 1
        return len(substrings) >= k
