class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            min_q = []
            max_q = []
            for j in range(i, min(n, i + k)):
                val = nums[j]
                while min_q and min_q[-1] > val:
                    min_q.pop()
                min_q.append(val)
                while max_q and max_q[-1] < val:
                    max_q.pop()
                max_q.append(val)
                total += min_q[0] + max_q[0]
        return total
