        n = len(s)
        ans = 0
        for i in range(n):
            last = int(s[i])
            if last == 0:
                continue
            val = 0
            pow10 = 1
            for j in range(i, max(-1, i-100), -1):
                val = (int(s[j]) * pow10 + val) % last
                pow10 = (pow10 * 10) % last
                if val == 0:
                    ans += 1
