class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        # precompute powers of 10 modulo d (1..9) up to 9 digits
        pow10 = [[1]*(10) for _ in range(10)]  # pow10[d][k] = (10**k) % d
        for d in range(1, 10):
            for k in range(1, 10):
                pow10[d][k] = (pow10[d][k-1] * 10) % d

        ans = 0
        for j in range(n):
            d = int(s[j])
            if d == 0:
                continue
            rem = 0
            # iterate backwards up to 9 digits
            for k in range(0, 10):
                i = j - k
                if i < 0:
                    break
                # add current digit at position i to remainder
                rem = (int(s[i]) * pow10[d][k] + rem) % d
                if rem == 0:
                    ans += 1
        return ans
