class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            d = int(s[i])
            if d != 0:
                ans += 1  # single-digit substring
            if d == 0:
                continue
            cur = 0
            pow10 = 1
            # consider substrings ending at i of length up to 100
            for j in range(i - 1, max(-1, i - 100) - 1, -1):
                digit = int(s[j])
                cur = (digit * pow10 + cur) % d
                if cur == 0:
                    ans += 1
                pow10 = (pow10 * 10) % d
        return ans
