class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def kmp_search(text: str, pat: str):
            n, m = len(text), len(pat)
            if m == 0:
                return list(range(n + 1))
            # build lps
            lps = [0] * m
            k = 0
            for i in range(1, m):
                while k > 0 and pat[k] != pat[i]:
                    k = lps[k - 1]
                if pat[k] == pat[i]:
                    k += 1
                lps[i] = k
            res = []
            q = 0
            for i in range(n):
                while q > 0 and pat[q] != text[i]:
                    q = lps[q - 1]
                if pat[q] == text[i]:
                    q += 1
                if q == m:
                    res.append(i - m + 1)
                    q = lps[q - 1]
            return res

        # split pattern
        first = p.find('*')
        second = p.find('*', first + 1)
        A = p[:first]
        B = p[first + 1:second]
        C = p[second + 1:]

        n = len(s)
        INF = 10 ** 9
        # occurrences
        a_pos = kmp_search(s, A)
        b_pos = kmp_search(s, B)
        c_pos = kmp_search(s, C)

        # build next arrays for B and C
        nextB = [INF] * (n + 1)
        for pos in b_pos:
            if pos <= n:
                nextB[pos] = pos
        for i in range(n - 1, -1, -1):
            if nextB[i] > nextB[i + 1]:
                nextB[i] = nextB[i + 1]

        nextC = [INF] * (n + 1)
        for pos in c_pos:
            if pos <= n:
                nextC[pos] = pos
        for i in range(n - 1, -1, -1):
            if nextC[i] > nextC[i + 1]:
                nextC[i] = nextC[i + 1]

        lenA, lenB, lenC = len(A), len(B), len(C)
        best = INF

        for a_start in a_pos:
            a_end = a_start + lenA - 1
            # position after A
            next_b = nextB[a_end + 1] if a_end + 1 <= n else INF
            if next_b == INF:
                continue
            # position after B
            next_c = nextC[next_b + lenB] if next_b + lenB <= n else INF
            if next_c == INF:
                continue
            length = (next_c + lenC) - a_start
            if length < best:
                best = length

        return -1 if best == INF else best
```

