class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def kmp_occurrences(text, pattern):
            if pattern == "":
                return list(range(len(text)+1))
            # build lps
            lps = [0]*len(pattern)
            k = 0
            for i in range(1, len(pattern)):
                while k>0 and pattern[k]!=pattern[i]:
                    k = lps[k-1]
                if pattern[k]==pattern[i]:
                    k += 1
                lps[i] = k
            # search
            res = []
            k = 0
            for i, ch in enumerate(text):
                while k>0 and pattern[k]!=ch:
                    k = lps[k-1]
                if pattern[k]==ch:
                    k += 1
                if k==len(pattern):
                    res.append(i-len(pattern)+1)
                    k = lps[k-1]
            return res

        a, b, c = p.split('*')
        len_a, len_b, len_c = len(a), len(b), len(c)

        pos_a = kmp_occurrences(s, a)
        pos_b = kmp_occurrences(s, b)
        pos_c = kmp_occurrences(s, c)

        if not pos_a or not pos_b or not pos_c:
            return -1

        import bisect
        best = float('inf')
        for i in pos_a:
            # find b after i+len_a
            idx_b = bisect.bisect_left(pos_b, i+len_a)
            if idx_b==len(pos_b): continue
            j = pos_b[idx_b]
            # find c after j+len_b
            idx_c = bisect.bisect_left(pos_c, j+len_b)
            if idx_c==len(pos_c): continue
            k = pos_c[idx_c]
            length = k+len_c - i
            if length < best:
                best = length
        return best if best!=float('inf') else -1
