class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        INF = -10**9
        # dp[l][r] is a list of best lengths for each cost 0..k
        dp = [[None]*n for _ in range(n)]
        for i in range(n):
            arr = [INF]*(k+1)
            arr[0] = 1  # single char palindrome
            dp[i][i] = arr
        for length in range(2, n+1):
            for l in range(0, n-length+1):
                r = l+length-1
                arr = [INF]*(k+1)
                # skip l
                if dp[l+1][r]:
                    for c in range(k+1):
                        if dp[l+1][r][c] > arr[c]:
                            arr[c] = dp[l+1][r][c]
                # skip r
                if dp[l][r-1]:
                    for c in range(k+1):
                        if dp[l][r-1][c] > arr[c]:
                            arr[c] = dp[l][r-1][c]
                # match l and r
                a = ord(s[l]) - 97
                b = ord(s[r]) - 97
                diff = abs(a-b)
                d = min(diff, 26-diff)  # minimal operations to make equal
                if d <= k and dp[l+1][r-1]:
                    for c in range(k+1-d):
                        newc = c+d
                        val = dp[l+1][r-1][c]
                        if val > INF:
                            if val+2 > arr[newc]:
                                arr[newc] = val+2
                dp[l][r] = arr
        best = 0
        for c in range(k+1):
            if dp[0][n-1][c] > best:
                best = dp[0][n-1][c]
        return best
