class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # precompute distance between letters
        dist = [[0]*26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                d = (b - a) % 26
                dist[a][b] = min(d, 26 - d)
        # dp[i][j] is list of max lengths for each cost 0..k
        dp = [[[-1]*(k+1) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i][0] = 1
        for length in range(2, n+1):
            for i in range(n-length+1):
                j = i + length -1
                # skip i
                for c in range(k+1):
                    dp[i][j][c] = max(dp[i][j][c], dp[i+1][j][c])
                # skip j
                for c in range(k+1):
                    dp[i][j][c] = max(dp[i][j][c], dp[i][j-1][c])
                # pair i and j
                cost_pair = dist[ord(s[i]) - 97][ord(s[j]) - 97]
                if cost_pair <= k:
                    inner = dp[i+1][j-1]
                    for c in range(k - cost_pair + 1):
                        if inner[c] != -1:
                            val = inner[c] + 2
                            dp[i][j][c + cost_pair] = max(dp[i][j][c + cost_pair], val)
        ans = 0
        for c in range(k+1):
            ans = max(ans, dp[0][n-1][c])
        return ans
