class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # precompute cost to make two chars equal
        cost = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                a = ord(s[i]) - 97
                b = ord(s[j]) - 97
                diff = abs(a - b)
                cost[i][j] = min(diff, 26 - diff)
        # DP[i][j] = dict cost -> max length achievable in substring i..j
        dp = [[{} for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i][0] = 1
        for length in range(2, n+1):
            for i in range(n-length+1):
                j = i + length - 1
                d = {}
                # try match i and j
                c = cost[i][j]
                if c <= k:
                    # inner substring
                    inner = dp[i+1][j-1] if i+1 <= j-1 else {0:0}
                    for inner_cost, inner_len in inner.items():
                        total_cost = inner_cost + c
                        if total_cost <= k:
                            d[total_cost] = max(d.get(total_cost, 0), inner_len + 2)
                # skip i
                for cst, val in dp[i+1][j].items():
                    d[cst] = max(d.get(cst, 0), val)
                # skip j
                for cst, val in dp[i][j-1].items():
                    d[cst] = max(d.get(cst, 0), val)
                dp[i][j] = d
        # answer is max length with cost <= k in dp[0][n-1]
        ans = 0
        for cst, val in dp[0][n-1].items():
            if cst <= k:
                ans = max(ans, val)
        return ans
