class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        INF = 10**9
        # precompute minimal steps to convert a to b
        step = [[0]*26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                step[a][b] = min((b-a)%26, (a-b)%26)
        # minimal cost to make s[i] and s[j] equal
        pairCost = [[INF]*n for _ in range(n)]
        for i in range(n):
            for j in range(i+1, n):
                ai, bj = ord(s[i])-97, ord(s[j])-97
                # choose target letter l minimizing step[ai][l]+step[bj][l]
                best = INF
                for l in range(26):
                    best = min(best, step[ai][l] + step[bj][l])
                pairCost[i][j] = best
        # dp[l][i][j] minimal cost to get palindrome of length l from s[i..j]
        dp = [[[INF]*n for _ in range(n)] for _ in range(n+1)]
        for i in range(n):
            dp[0][i][i] = 0
            dp[1][i][i] = 0
        for l in range(2, n+1):
            for i in range(n-1, -1, -1):
                for j in range(i, n):
                    # skip i
                    if i+1 <= j:
                        dp[l][i][j] = min(dp[l][i][j], dp[l][i+1][j])
                    # skip j
                    if i <= j-1:
                        dp[l][i][j] = min(dp[l][i][j], dp[l][i][j-1])
                    if i < j and l >= 2:
                        inner = dp[l-2][i+1][j-1] if l-2 >= 0 else 0
                        if inner < INF:
                            dp[l][i][j] = min(dp[l][i][j], pairCost[i][j] + inner)
        ans = 0
        for l in range(1, n+1):
            if dp[l][0][n-1] <= k:
                ans = l
        return ans
