class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        n = len(t)
        i = 0
        max0 = -1
        min1 = 10**9
        while i < n:
            j = i
            while j < n and t[j] == t[i]:
                j += 1
            length = j - i
            if t[i] == '0':
                if i > 0 and j < n and t[i-1] == '1' and t[j] == '1':
                    max0 = max(max0, length)
            else:  # '1'
                if i > 0 and j < n and t[i-1] == '0' and t[j] == '0':
                    min1 = min(min1, length)
            i = j
        orig = s.count('1')
        if max0 == -1 or min1 == 10**9:
            return orig
        trade_gain = max0 - min1
        return max(orig, orig + trade_gain)
```

