class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        # Augment with '1' at both ends
        t = '1' + s + '1'
        zero_runs_between_ones = []
        one_runs_between_zeros = []
        i = 0
        while i < len(t):
            j = i
            while j < len(t) and t[j] == t[i]:
                j += 1
            run_len = j - i
            if t[i] == '0':
                # check surrounded by '1's
                if t[i-1] == '1' and t[j] == '1':
                    zero_runs_between_ones.append(run_len)
            else:
                # '1' run
                if t[i-1] == '0' and t[j] == '0':
                    one_runs_between_zeros.append(run_len)
            i = j
        total_ones = s.count('1')
        if not zero_runs_between_ones or not one_runs_between_zeros:
            return total_ones
        max_zero = max(zero_runs_between_ones)
        min_one = min(one_runs_between_zeros)
        gain = max_zero - min_one
        if gain <= 0:
            return total_ones
        return total_ones + gain
```

