class Solution:
    def minOperations(self, queries: list[list[int]]) -> int:
        pow4 = [1]
        while pow4[-1] <= 10**9:
            pow4.append(pow4[-1] * 4)
        res = 0
        for l, r in queries:
            total = 0
            for k in range(len(pow4)-1):
                a, b = pow4[k], pow4[k+1] - 1
                left = max(l, a)
                right = min(r, b)
                if left <= right:
                    total += (right - left + 1) * (k + 1)
            res += (total + 1) // 2
        return res
```

