class Solution:
    def minOperations(self, queries):
        import math
        powers = [1]
        while powers[-1] <= 10**9:
            powers.append(powers[-1] * 4)
        total = 0
        for l, r in queries:
            ops = 0
            for p in powers:
                if p > r:
                    break
                if r < p:
                    continue
                start = l if l > p else p
                cnt = r - start + 1
                ops += (cnt + 1) // 2
            total += ops
        return total
