class Solution:
    def minOperations(self, queries):
        powers = [1]
        while powers[-1] <= 10**9:
            powers.append(powers[-1] * 4)
        total_ops = 0
        for l, r in queries:
            sum_counts = 0
            for k in range(1, len(powers)):
                start = max(l, powers[k-1])
                end = min(r, powers[k]-1)
                if start <= end:
                    sum_counts += (end - start + 1) * k
                if powers[k] > r:
                    break
            total_ops += (sum_counts + 1) // 2
        return total_ops
```

