class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        total = n * (n + 1) // 2
        sum_all = 0
        max_contrib = 0
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            contrib = a * (n - b + 1)
            sum_all += contrib
            if contrib > max_contrib:
                max_contrib = contrib
        return total - sum_all + max_contrib
